window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-07-30"]={"date":"2026-07-30","dateKR":"2026년 7월 30일","dateEN":"30 July 2026","total":97,"sections":[{"code":"TOP","type":"news","kTitle":"Section 1. 주요 뉴스","eTitle":"Section 1. Top News","items":[{"code":"TOP","title":"U.S. Launches Heavy Wave of Strikes on Iran","src":"Maritime Executive","date":"2026-07-29","kSum":"미국 중부사령부(CENTCOM)는 2026년 7월 29일 요르단 내 미군 기지에 대한 이란의 미사일 공격에 대응해 이란 진지에 대규모 공습을 감행했다. 지휘소, 드론·미사일 발사장, 연안 감시시설, 이란혁명수비대(IRGC)의 소형 공격정 등 수십 개 표적을 타격했다.","eSum":"On 29 July 2026 U.S. Central Command carried out a heavy wave of strikes on Iranian positions in response to Iranian missile attacks on U.S. bases in Jordan. Targets included command centers, drone and missile launch sites, coastal surveillance sites and IRGC attack speedboats.","kImp":"걸프·호르무즈 해협 긴장 고조로 유조선 등 상선 항로 위험이 커진다.","eImp":"Escalation raises the risk to tanker and merchant traffic through the Gulf and Strait of Hormuz.","url":"https://maritime-executive.com/article/u-s-launches-heavy-wave-of-strikes-on-iran"},{"code":"TOP","title":"Houthis Target Saudi Chemical Tanker","src":"Seatrade Maritime","date":"2026-07-29","kSum":"예멘 후티 반군이 2026년 7월 29일 사우디아라비아와 연계된 케미컬 탱커를 겨냥해 공격했다고 시트레이드가 보도했다. 후티의 사우디 항만 봉쇄 선언 이후 사우디 연계 유조선에 대한 공격이 이어지고 있다.","eSum":"Yemen's Houthis targeted a Saudi-linked chemical tanker on 29 July 2026, continuing a series of attacks on Saudi-connected tankers following their declared blockade of Saudi ports.","kImp":"홍해·바브엘만데브 항로의 상선 안전과 보험료에 부정적 영향을 준다.","eImp":"The attacks undermine merchant safety and raise insurance costs on Red Sea and Bab el-Mandeb routes.","url":"https://www.seatrade-maritime.com/security/houthi-target-saudi-chemical-tanker"},{"code":"TOP","title":"Vafias Stacks Up More Tanker Orders in South Korea","src":"Splash247","date":"2026-07-30","kSum":"그리스 선주 바피아스(Vafias) 그룹이 한국 조선소에 유조선을 추가 발주했다고 스플래시247이 2026년 7월 30일 보도했다. 견조한 탱커 시장 전망 속에 신조 프로그램을 확대하는 움직임이다.","eSum":"Greek owner the Vafias group has placed further tanker newbuilding orders in South Korea, Splash247 reported on 30 July 2026, expanding its newbuilding programme amid a firm tanker market outlook.","kImp":"한국 조선소의 탱커 수주 지속과 탱커 선대 확장 흐름을 보여준다.","eImp":"It reflects continued tanker ordering at Korean yards and ongoing fleet expansion.","url":"https://splash247.com/vafias-stacks-up-more-tanker-orders-in-south-korea/"},{"code":"TOP","title":"Blystad Books Up to Six Feeders at Chinese Newcomer","src":"Splash247","date":"2026-07-30","kSum":"노르웨이의 블리스타드(Blystad) 그룹이 중국 신생 조선소에 최대 6척의 피더 컨테이너선을 발주했다고 스플래시247이 2026년 7월 30일 보도했다. 피더 부문 신조 발주가 이어지고 있다.","eSum":"Norway's Blystad group has booked up to six feeder containerships at a Chinese newcomer yard, Splash247 reported on 30 July 2026, as feeder newbuilding activity continues.","kImp":"피더 선대 확충과 중국 신생 조선소의 수주 확대를 시사한다.","eImp":"It signals feeder fleet growth and rising order intake at emerging Chinese yards.","url":"https://splash247.com/blystad-books-up-to-six-feeders-at-chinese-newcomer/"},{"code":"TOP","title":"W Marine Broadens Newbuild Drive With Ultramaxes","src":"Splash247","date":"2026-07-30","kSum":"W 마린(W Marine)이 울트라막스 벌크선으로 신조 프로그램을 확대했다고 스플래시247이 2026년 7월 30일 전했다. 건화물 선대 확충 흐름의 일부다.","eSum":"W Marine has broadened its newbuilding drive with ultramax bulk carriers, Splash247 reported on 30 July 2026, part of continued dry bulk fleet renewal.","kImp":"건화물 신조 발주 지속과 울트라막스 수요를 보여준다.","eImp":"It shows sustained dry bulk ordering and ultramax demand.","url":"https://splash247.com/w-marine-broadens-newbuild-drive-with-ultramaxes/"},{"code":"TOP","title":"Jinhui Doubles Down on Newbuild Financing","src":"Splash247","date":"2026-07-30","kSum":"진후이(Jinhui)가 신조선 금융을 확대했다고 스플래시247이 2026년 7월 30일 보도했다. 벌크 선사들의 신조·금융 활동이 활발하다.","eSum":"Jinhui is doubling down on newbuild financing, Splash247 reported on 30 July 2026, amid active newbuilding and financing among bulker owners.","kImp":"벌커 선주들의 신조 투자와 금융 조달 확대를 반영한다.","eImp":"It reflects growing newbuild investment and financing among bulker owners.","url":"https://splash247.com/jinhui-doubles-down-on-newbuild-financing/"},{"code":"TOP","title":"DP World-Backed Bid for Lyttelton Port Rejected","src":"Splash247","date":"2026-07-30","kSum":"DP월드가 참여한 뉴질랜드 리틀턴(Lyttelton)항 인수 제안이 거부됐다고 스플래시247이 2026년 7월 30일 전했다. 항만 인수합병 시도가 무산됐다.","eSum":"A DP World-backed bid for New Zealand's Lyttelton Port has been rejected, Splash247 reported on 30 July 2026, ending the port takeover attempt.","kImp":"글로벌 터미널 운영사의 항만 인수 확장에 제동이 걸렸다.","eImp":"It checks a global terminal operator's port-acquisition expansion.","url":"https://splash247.com/dp-world-backed-bid-for-lyttelton-port-rejected/"},{"code":"TOP","title":"U.S. Highlights Cooperation With Taiwan's Coast Guard, Risking China's Ire","src":"Maritime Executive","date":"2026-07-29","kSum":"미국 재대만협회(AIT)는 2026년 7월 29일 미국·대만 해안경비대의 합동 순찰을 공개 확인했다. 중국의 대만 EEZ 침범 논란 직후 나온 이례적 안보협력 발표로, 중국의 반발이 예상된다.","eSum":"On 29 July 2026 the American Institute in Taiwan publicized a joint U.S.-Taiwan Coast Guard patrol, a rare announcement of security cooperation following a disputed Chinese incursion into Taiwan's EEZ, likely to provoke Beijing.","kImp":"대만해협 주변 해양 안보 긴장과 상선 리스크 요인이 될 수 있다.","eImp":"It adds to maritime security tension around the Taiwan Strait, a potential risk to merchant shipping.","url":"https://maritime-executive.com/article/u-s-highlights-cooperation-with-taiwan-s-coast-guard-risking-china-s-ire"},{"code":"TOP","title":"Borr Drilling Buys Paratus' Jack-Up Fleet for Mexican Market","src":"Maritime Executive","date":"2026-07-29","kSum":"오슬로 상장 보르 드릴링(Borr Drilling)이 멕시코 해양 시장 합작법인을 통해 옛 시드릴 선대의 잭업 리그 5기를 약 2억8,700만 달러에 인수했다고 2026년 7월 29일 보도됐다. 리그는 모두 멕시코 해역에 있다.","eSum":"Oslo-listed Borr Drilling has acquired five former Seadrill jack-up rigs through its Mexican JV for about $287 million, reported on 29 July 2026; all the rigs are in Mexican waters.","kImp":"해양시추 리그 시장의 재편과 멕시코 시장 확대를 보여준다.","eImp":"It illustrates consolidation in the offshore rig market and expansion in Mexico.","url":"https://maritime-executive.com/article/borr-drilling-buys-paratus-jack-up-fleet-for-mexican-market"}]},{"code":"ACC","type":"accident","kTitle":"Section 2. 해양사고","eTitle":"Section 2. Accidents & Casualties","items":[{"code":"ACC","title":"노르웨이 황산 운반 탱커 베르그스트라움(Bergstraum) 폭발·화재","src":"Maritime Executive","date":"2026-07-28","kSum":"케미컬 탱커 베르그스트라움(Bergstraum, 9,494 DWT)이 2026년 7월 28일 오후 노르웨이 프레드릭스타드(Fredrikstad) 인근 오슬로피오르 입구 남쪽에서 빈 화물탱크 폭발로 화재가 발생했다. 선박은 황산을 싣고 있었으며 발트·필리핀 국적 선원 15명 전원이 부상 없이 대피 준비를 마쳤고, 구조선·경비정·소방정이 출동해 화재를 조기 진압했다.","eSum":"The chemical tanker Bergstraum (9,494 dwt) suffered an explosion in an empty cargo tank and a fire off Fredrikstad, Norway on 28 July 2026 while carrying sulfuric acid. All 15 Baltic and Filipino crew were accounted for without injury; rescue boats, police boats and a fireboat responded and the crew brought the blaze under control with foam.","kCause":"빈 화물탱크 내부 폭발로 발생했으며 정확한 원인은 조사 중(추정).","eCause":"An explosion in an empty cargo tank; exact cause under investigation (presumed).","kLes":"위험 화물 운반선은 빈 탱크의 가스·증기 관리와 폭발 위험 통제가 필수적이다.","eLes":"Vessels carrying hazardous cargo must rigorously manage vapors in empty tanks to control explosion risk.","url":"https://maritime-executive.com/article/explosion-and-fire-on-norwegian-tanker-carrying-sulfuric-acid"},{"code":"ACC","title":"인도네시아 예인선 AOM 787(AOM 787) 전복, 한국 컨테이너선이 선원 4명 구조","src":"Maritime Executive","date":"2026-07-27","kSum":"인도네시아 예인선 AOM 787이 아남바스 제도 인근에서 빈 바지선을 예인하던 중 악천후로 복원성을 잃고 정오경 전복됐다. 선원 4명은 구명뗏목으로 퇴선했고, 인근을 지나던 컨테이너선 상하이 보이저(Shanghai Voyager)가 신호탄을 발견해 전원 구조한 뒤 인도네시아 SAR에 인계했다(2026년 7월 27일 보도).","eSum":"The Indonesian tug AOM 787 capsized near the Anambas Islands after losing stability in heavy weather while towing an empty barge; her four crew abandoned ship into a liferaft. The passing container ship Shanghai Voyager spotted their flares, rescued all four and handed them to Indonesian SAR at Matak (reported 27 July 2026).","kCause":"악천후 속 복원성 상실로 전복(추정); 예인줄을 끊었으나 전복 방지 실패.","eCause":"Loss of stability in stormy conditions led to capsize (presumed); cutting the towline did not prevent it.","kLes":"소형 예인선은 악천후 시 복원성 한계와 완전한 조난신호 장비(EPIRB·조명탄) 구비가 중요하다.","eLes":"Small tugs must respect stability limits in heavy weather and carry a full complement of distress-signaling devices (EPIRB, flares).","url":"https://maritime-executive.com/article/korean-container-ship-rescues-tug-crewmembers-in-south-china-sea"},{"code":"ACC","title":"화물선 오네고 오트라(Onego Otra) 세인트로렌스강 좌초 후 이초 성공","src":"Maritime Executive","date":"2026-07-28","kSum":"곡물을 싣고 6월 30일 몬트리올을 떠나 뉴올리언스로 향하던 화물선 오네고 오트라(Onego Otra, 10,872 DWT)가 방향타 고장으로 세인트로렌스강 일 생투르 인근에서 항로를 벗어나 수주간 좌초 상태였다. 캐나다 해안경비대는 2026년 7월 28일 선박이 이초됐다고 확인했으며 손상 여부 점검이 진행 중이다.","eSum":"The cargo ship Onego Otra (10,872 dwt), which grounded in the St. Lawrence River near Ile Saint-Ours after a rudder problem while carrying grain from Montreal to New Orleans, was refloated after several weeks. The Canadian Coast Guard confirmed the refloating on 28 July 2026 and the vessel is undergoing damage inspections.","kCause":"방향타 고장으로 항로를 이탈해 좌초.","eCause":"A rudder failure caused the vessel to veer off course and ground.","kLes":"좁은 수로 항해 시 조타 장치 신뢰성과 신속한 이초·구난 계획이 중요하다.","eLes":"Steering-gear reliability and prompt salvage planning are critical when transiting narrow rivers.","url":"https://maritime-executive.com/article/cargo-ship-stuck-for-weeks-is-refloated-in-the-st-lawrence-river"},{"code":"ACC","title":"이집트 다미에타(Damietta)항 FSRU·LNG선 드론 피격 화재","src":"Seatrade Maritime","date":"2026-07-30","kSum":"2026년 7월 30일 이집트 다미에타항에서 에너고스(Energos) 부유식 저장·재기화설비(FSRU)와 LNG 운반선이 드론 공격을 받아 화재가 발생했다. 지중해 연안 에너지 인프라를 겨냥한 공격으로 지역 해상 보안 우려가 커지고 있다.","eSum":"On 30 July 2026 a drone strike hit an Energos floating storage and regasification unit (FSRU) and an LNG carrier at Egypt's Damietta port, sparking a fire. The attack on Mediterranean energy infrastructure has heightened regional maritime security concerns.","kCause":"드론 공격에 의한 피격·화재.","eCause":"A drone strike caused the impact and fire.","kLes":"항만 내 에너지 인프라와 가스선은 무인기 위협에 대한 방호·대응 태세가 필요하다.","eLes":"Port energy infrastructure and gas carriers need enhanced protection and response against drone threats.","url":"https://www.seatrade-maritime.com/security/drone-strike-hits-energos-fsru-and-a-lng-carrier-in-egypt-s-damietta-port"},{"code":"ACC","title":"일반화물선 골든 레오(Golden Leo) 러시아 미사일 피격 후 침몰","src":"Seatrade Maritime","date":"2026-07-27","kSum":"옥수수를 싣고 초르노모르스크를 출항한 일반화물선 골든 레오(Golden Leo, 7,300 DWT)가 7월 19일 오데사 앞바다에서 다수의 미사일에 피격돼 우크라이나 도선사 등 선원 10명이 사망하고 8명이 구조됐다. 선박은 손상 누적으로 주말 사이 흑해에서 침몰했다고 우크라이나 당국이 2026년 7월 27일 밝혔다.","eSum":"The general cargo ship Golden Leo (7,300 dwt), which had departed Chornomorsk with corn, was struck by multiple missiles off Odesa on 19 July, killing 10 seafarers including a Ukrainian pilot; eight were rescued. Ukrainian authorities said on 27 July 2026 the vessel sank in the Black Sea over the weekend from accumulated damage.","kCause":"러시아군 미사일 공격에 의한 피격 및 손상 누적으로 침몰.","eCause":"A Russian missile strike caused fatal damage that led to the sinking.","kLes":"흑해 분쟁 수역 항해 선박과 선원 보호를 위한 위험 회피·전쟁위험 대책이 시급하다.","eLes":"Vessels transiting Black Sea conflict zones need robust risk-avoidance and war-risk measures to protect crews.","url":"https://www.seatrade-maritime.com/security/golden-leo-sinks-after-deadly-russian-missile-strike"},{"code":"ACC","title":"러시아, 오데사 인근 선박 2척 추가 공격 주장","src":"Maritime Executive","date":"2026-07-29","kSum":"러시아 국방부는 2026년 7월 29일 오데사 항 인근에서 선박 2척과 항만 인프라를 타격했다고 주장했다. 러시아는 해당 선박들이 우크라이나군 무기를 운반했다고 밝혔으나, 흑해 항로는 우크라이나 곡물 수출 등 민간 물류의 핵심 통로다.","eSum":"Russia's defense ministry claimed on 29 July 2026 that its forces struck two more ships near the port of Odesa along with shoreside infrastructure, alleging the vessels carried arms. The Black Sea corridor remains vital for Ukraine's civilian trade, including grain exports.","kCause":"러시아군의 항만·선박 공격(전쟁 행위).","eCause":"Russian military strikes on ships and port infrastructure (act of war).","kLes":"흑해 항만·선박에 대한 지속적 공격은 곡물 수출과 선원 안전에 중대한 위협이다.","eLes":"Continued strikes on Black Sea ports and ships pose serious threats to grain exports and seafarer safety.","url":"https://maritime-executive.com/article/russia-claims-strikes-on-two-more-ships-near-odesa"}]},{"code":"PSC","type":"news","kTitle":"Section 3. 항만국통제(PSC)","eTitle":"Section 3. Port State Control","items":[{"code":"PSC","title":"RightShip and NorthStandard Move to Cut Duplicate Ship Inspections","src":"Splash247","date":"2026-07-29","kSum":"선박 심사기관 라이트십(RightShip)과 선주상호보험사 노스스탠다드(NorthStandard)가 검사 보고서를 공유해 중복 선박 검사를 줄이기로 했다고 스플래시247이 2026년 7월 29일 보도했다. 선주·관리사의 반복 검사 준비 부담을 줄이려는 조치다.","eSum":"Ship vetting body RightShip and marine insurer NorthStandard are moving to cut duplicate ship inspections by sharing inspection reports, Splash247 reported on 29 July 2026, aiming to reduce the burden of repeated inspection preparation on owners and managers.","kImp":"검사·심사 체계의 중복을 줄여 항만국통제(PSC)·심사 부담과 비용을 완화할 수 있다.","eImp":"Streamlining overlapping inspection regimes could ease PSC and vetting burdens and costs for operators.","url":"https://splash247.com/rightship-and-northstandard-move-to-cut-duplicate-ship-inspections/"}]},{"code":"PCTC","type":"news","kTitle":"Section 4. 자동차운반선 시장(PCTC)","eTitle":"Section 4. Car Carrier Market (PCTC)","items":[{"code":"PCTC","title":"Sallaum Lines Expands Car Carrier Orderbook With Fresh China Deal","src":"Splash247","date":"2026-07-29","kSum":"스위스 살라움 라인스(Sallaum Lines)가 중국 초상국(China Merchants) 조선소에 8,600 CEU급 자동차운반선(PCTC) 1척(옵션 1척 포함)을 추가 발주했다고 스플래시247이 2026년 7월 29일 전했다. LNG 이중연료·암모니아 대응형으로 2029년 인도 예정이며, 이로써 살라움의 신조 프로그램은 9척(투자액 8억5,000만 달러 이상)으로 늘었다.","eSum":"Swiss operator Sallaum Lines has ordered another 8,600 CEU pure car and truck carrier (plus one option) at China Merchants Shipyard, Splash247 reported on 29 July 2026. The LNG dual-fuel, ammonia-ready ship is due in 2029, lifting Sallaum's newbuilding programme to nine vessels worth more than $850m.","kImp":"자동차운반선 시장의 강세 속 신조 발주와 친환경 연료 전환이 지속됨을 보여준다.","eImp":"It underlines continued PCTC newbuild ordering and the shift to alternative fuels amid a strong car-carrier market.","url":"https://splash247.com/sallaum-lines-expands-car-carrier-orderbook-with-fresh-china-deal/"}]},{"code":"WW","type":"news","kTitle":"Section 5. 발레니우스 빌헬름센","eTitle":"Section 5. Wallenius Wilhelmsen","items":[{"code":"WW","title":"Wallenius Wilhelmsen Takes Delivery of Methanol Dual-Fuel Car Carrier Arctic Tern","src":"Baird Maritime","date":"2026-07-10","kSum":"발레니우스 빌헬름센(Wallenius Wilhelmsen)이 중국 초상국진링(China Merchants Jinling) 조선소에서 건조한 신형 자동차운반선(PCTC) 아크틱 턴(Arctic Tern)을 2026년 7월 10일 인도받았다. 메탄올 이중연료 추진의 셰이퍼(Shaper) 클래스 1번선으로, 합작 선사 유코(EUKOR)를 통해 아시아-유럽 항로에 투입되며 총 14척 시리즈의 첫 선박이다.","eSum":"Wallenius Wilhelmsen took delivery of Arctic Tern, a new methanol dual-fuel pure car and truck carrier built by China Merchants Jinling Shipyard, on 10 July 2026. The lead ship of the 14-vessel Shaper Class (9,300 CEU) will be operated by joint venture EUKOR on the Asia-Europe trade.","kImp":"발레니우스 빌헬름센의 2027년 넷제로 서비스 목표를 뒷받침하는 친환경 선대 전환의 핵심 이정표다.","eImp":"It is a key milestone in Wallenius Wilhelmsen's green fleet transition toward its 2027 net-zero service ambition.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/wallenius-wilhelmsen-takes-delivery-of-methanol-dual-fuel-car-carrier"},{"code":"WW","title":"Tirranna's wing sail installation completed, marking new wind-propulsion phase","src":"Wallenius Wilhelmsen","date":"2026-07-02","kSum":"발레니우스 빌헬름센(Wallenius Wilhelmsen)이 RoRo선 티란나(Tirranna)에 윙세일(wing sail) 설치를 완료하고 상업 운항 중 풍력보조추진(WAPS) 실증 단계에 들어갔다. 설치는 6월 22~24일 로테르담 다멘조선소(Damen Shipyard)에서 이뤄졌고, 해상시운전(SAT)은 7월 1일 완료됐다. 이번 실증은 오르셀레 호라이즌(Orcelle Horizon) 프로젝트의 일환으로 오션버드(Oceanbird)·DNV 등 11개 파트너가 참여하며 EU 자금 지원을 받는다.","eSum":"Wallenius Wilhelmsen has completed a wing sail installation on the RoRo vessel Tirranna, entering a full-scale test of wind-assisted propulsion in commercial operation. The installation took place on 22-24 June at Damen Shipyard in Rotterdam, with the sea acceptance test completed on 1 July. It forms part of the EU-funded Orcelle Horizon project involving eleven partners including Oceanbird and DNV.","kImp":"선대 최대 선사 중 하나가 실선에서 풍력보조추진을 검증하는 것으로, PCTC/RoRo 부문의 실질적 연료 절감·탈탄소 경로를 가늠하는 시금석이다.","eImp":"A leading car-carrier operator validating wind propulsion on an in-service ship is a bellwether for practical fuel-saving and decarbonization pathways in the PCTC/RoRo segment.","url":"https://www.walleniuswilhelmsen.com/news/with-wind-in-her-sail-tirrannas-wing-sail-installation-completed"}]},{"code":"EE","type":"news","kTitle":"Section 6. 에너지효율·탈탄소","eTitle":"Section 6. Energy Efficiency & Decarbonization","items":[{"code":"EE","title":"GTT Sees Need for Another 550 LNG Carriers by 2035","src":"Splash247","date":"2026-07-30","kSum":"프랑스 GTT가 2035년까지 추가로 550척의 LNG 운반선이 필요할 것으로 전망했다고 스플래시247이 2026년 7월 30일 보도했다. LNG 무역 및 이중연료 수요 확대에 따른 선대 증강 필요성을 제시했다.","eSum":"France's GTT projects a need for another 550 LNG carriers by 2035, Splash247 reported on 30 July 2026, citing expanding LNG trade and dual-fuel demand driving fleet growth.","kImp":"LNG 연료·무역 확대가 해운 에너지 전환의 핵심 축임을 보여준다.","eImp":"It highlights LNG's central role in shipping's fuel and trade transition.","url":"https://splash247.com/gtt-sees-need-for-another-550-lng-carriers-by-2035/"},{"code":"EE","title":"UK Launches Accelerated Auction for Abandoned Offshore Wind Site","src":"Maritime Executive","date":"2026-07-27","kSum":"영국 크라운에스테이트(The Crown Estate)가 아일랜드해의 대형 해상풍력 부지(모건 프로젝트)에 대한 신규 경쟁 입찰을 개시했다고 마리타임이그제큐티브가 2026년 7월 27일 전했다. 개발 일정을 앞당기고 신규 입찰자의 리스크를 낮추도록 설계됐다.","eSum":"The Crown Estate has launched a new competitive tender for a large offshore wind site (the Morgan project) in the Irish Sea, Maritime Executive reported on 27 July 2026, designed to accelerate development and de-risk the project for new bidders.","kImp":"해상풍력 개발 가속은 해양 에너지 전환과 관련 선박 수요에 영향을 준다.","eImp":"Accelerated offshore wind development supports the marine energy transition and related vessel demand.","url":"https://maritime-executive.com/article/uk-launches-accelerated-auction-for-abandoned-offshore-wind-site"}]},{"code":"DIG","type":"news","kTitle":"Section 7. 해운 디지털화","eTitle":"Section 7. Maritime Digitalization","items":[{"code":"DIG","title":"LD Armateurs' Sustainability Report Maps Digital Procurement Strategy","src":"Digital Ship","date":"2026-07-29","kSum":"LD 아르마퇴르(LD Armateurs)의 2025 지속가능성 보고서가 디지털 조달·계약관리 시스템을 통해 공급업체 거버넌스를 강화하는 전략을 제시했다고 디지털십이 2026년 7월 29일 보도했다. 디지털 조달 표준화가 핵심이다.","eSum":"LD Armateurs' 2025 Sustainability Report maps out a digital procurement and contract-management strategy to strengthen supplier governance, Digital Ship reported on 29 July 2026, centering on standardized digital procurement.","kImp":"해운사의 디지털 조달·공급망 거버넌스 고도화 흐름을 보여준다.","eImp":"It shows shipowners advancing digital procurement and supply-chain governance.","url":"https://thedigitalship.com/news/maritime-software/ld-armateurss-sustainability-report-maps-digital-procurement-strategy-for-stronger-supplier-governance/"},{"code":"DIG","title":"BV Approves Seatrium's 30 MW Floating Data Centre Concept","src":"Digital Ship","date":"2026-07-29","kSum":"뷰로베리타스(BV)가 시트리움(Seatrium)의 30MW급 부유식 데이터센터 개념설계에 대해 원칙승인(AiP)을 부여했다고 디지털십이 2026년 7월 29일 전했다. 해양 인프라의 디지털 시대 진입을 상징한다.","eSum":"Bureau Veritas has granted Approval in Principle to Seatrium's 30 MW floating data centre concept, Digital Ship reported on 29 July 2026, marking offshore infrastructure's move into the digital era.","kImp":"해상 부유식 데이터센터 등 해양 디지털 인프라의 새로운 시장을 예고한다.","eImp":"It signals a new market for offshore digital infrastructure such as floating data centres.","url":"https://thedigitalship.com/news/maritime-software/bv-approves-seatriums-30-mw-floating-data-centre-concept-as-offshore-infrastructure-enters-the-digital-era/"},{"code":"DIG","title":"Maersk Links E-Commerce Logistics With ShippyPro","src":"Digital Ship","date":"2026-07-28","kSum":"머스크(Maersk)가 배송관리 플랫폼 쉬피프로(ShippyPro)와 제휴해 전자상거래 물류 서비스를 멀티캐리어 플랫폼에 직접 통합했다고 디지털십이 2026년 7월 28일 보도했다. 선사들의 디지털 공급망 역량 확장 사례다.","eSum":"A.P. Moller-Maersk has partnered with shipping management platform ShippyPro to integrate its e-commerce logistics services directly into ShippyPro's multi-carrier platform, Digital Ship reported on 28 July 2026, as shipowners widen digital supply-chain capabilities.","kImp":"해운·물류의 전자상거래 디지털 통합 확대를 보여준다.","eImp":"It reflects growing e-commerce digital integration across shipping and logistics.","url":"https://thedigitalship.com/news/maritime-software/maersk-links-e-commerce-logistics-with-shippypro-as-shipowners-widen-digital-supply-chain-capabilities/"},{"code":"DIG","title":"PETRONAS Charters Adopt Integrated GTT Marine Platform","src":"Digital Ship","date":"2026-07-27","kSum":"페트로나스(PETRONAS)가 용선한 LNG선 선대에 GTT 마린(GTT Marine)의 통합 디지털 플랫폼을 도입해 선박 데이터와 항해 최적화를 통합하기로 했다고 디지털십이 2026년 7월 27일 전했다.","eSum":"PETRONAS-chartered LNG carriers will adopt GTT Marine's integrated digital platform to unify vessel data and voyage optimisation, Digital Ship reported on 27 July 2026.","kImp":"LNG 선대의 데이터 통합·항해 최적화 등 디지털 운영 고도화를 보여준다.","eImp":"It shows advancing digital operations, including data integration and voyage optimisation, across LNG fleets.","url":"https://thedigitalship.com/news/maritime-software/petronas-charters-adopt-integrated-gtt-marine-platform-to-unify-vessel-data-and-voyage-optimisation/"},{"code":"DIG","title":"Freight Automation Startup 5U AI Lands $3.2m","src":"Splash247","date":"2026-07-30","kSum":"화물 자동화 스타트업 5U AI가 320만 달러를 유치했다고 스플래시247이 2026년 7월 30일 보도했다. 물류·화물 업무 자동화에 대한 투자 관심을 반영한다.","eSum":"Freight automation startup 5U AI has raised $3.2m, Splash247 reported on 30 July 2026, reflecting investor interest in automating logistics and freight workflows.","kImp":"해운·물류 자동화 스타트업에 대한 투자 확대를 보여준다.","eImp":"It signals growing investment in shipping and logistics automation startups.","url":"https://splash247.com/freight-automation-startup-5u-ai-lands-3-2m/"},{"code":"DIG","title":"Machine Learning Seen Sharpening Freight Forecasts","src":"Splash247","date":"2026-07-29","kSum":"머신러닝이 운임 예측의 정확도를 높일 수 있다는 분석이 제기됐다고 스플래시247이 2026년 7월 29일 전했다. 데이터 기반 운임 전망 도구의 발전을 다뤘다.","eSum":"Machine learning is seen sharpening freight-rate forecasts, Splash247 reported on 29 July 2026, highlighting advances in data-driven rate prediction tools.","kImp":"데이터·AI 기반 시황 예측이 상업적 의사결정에 확산되고 있음을 보여준다.","eImp":"It shows data and AI-driven market forecasting spreading into commercial decision-making.","url":"https://splash247.com/machine-learning-seen-sharpening-freight-forecasts/"},{"code":"DIG","title":"The Hard Truth About Maritime Autonomy","src":"Splash247","date":"2026-07-29","kSum":"해상 자율운항의 현실적 과제를 짚은 분석이 스플래시247에 2026년 7월 29일 게재됐다. 자율운항 기술의 기대와 실제 도입 간 격차를 다뤘다.","eSum":"A Splash247 analysis published on 29 July 2026 examines the hard truths of maritime autonomy, addressing the gap between expectations and real-world adoption of autonomous technology.","kImp":"자율운항의 상용화가 여전히 기술·규제 과제에 직면해 있음을 시사한다.","eImp":"It underscores that maritime autonomy still faces significant technical and regulatory hurdles.","url":"https://splash247.com/the-hard-truth-about-maritime-autonomy/"},{"code":"DIG","title":"APM Terminals Deepens Automation Partnership With Kalmar","src":"Splash247","date":"2026-07-30","kSum":"APM 터미널스가 칼마르(Kalmar)와 자동화 파트너십을 심화한다고 스플래시247이 2026년 7월 30일 보도했다. 터미널 장비 자동화 확대의 일환이다.","eSum":"APM Terminals is deepening its automation partnership with Kalmar, Splash247 reported on 30 July 2026, part of expanding terminal-equipment automation.","kImp":"항만 터미널의 자동화·디지털화 가속을 보여준다.","eImp":"It reflects accelerating automation and digitalization at port terminals.","url":"https://splash247.com/apm-terminals-deepens-automation-partnership-with-kalmar/"},{"code":"DIG","title":"AI and Tracking the Dark Fleet","src":"Seatrade Maritime","date":"2026-07-30","kSum":"시트레이드 마리타임이 2026년 7월 30일 인공지능(AI)을 활용한 '다크 플리트(dark fleet)' 추적을 다룬 팟캐스트를 공개했다. AI·데이터 분석이 제재 회피 선박 감시에 활용되는 사례를 조명했다.","eSum":"Seatrade Maritime published a podcast on 30 July 2026 on using artificial intelligence to track the 'dark fleet', highlighting how AI and data analytics are being applied to monitor sanctions-evading vessels.","kImp":"AI·데이터가 해상 제재 이행과 선박 감시에 점점 더 중요해지고 있음을 보여준다.","eImp":"It shows AI and data becoming increasingly central to sanctions enforcement and vessel monitoring.","url":"https://www.seatrade-maritime.com/maritime-technology/ai-and-tracking-the-dark-fleet"}]},{"code":"TECH","type":"news","kTitle":"Section 8. 기술팀","eTitle":"Section 8. Technical","items":[{"code":"TECH","title":"South Africa drydocks largest vessel in more than a decade","src":"Maritime Executive","date":"2026-07-29","kSum":"남아프리카공화국 트란스넷(Transnet) 국가항만청이 10여 년 만에 최대 규모 선박을 입거시켰다. 7만3180DWT 유조선 트로이(Troy)호가 더반(Durban)의 1924년 준공된 프린스에드워드 그레이빙독(Prince Edward Graving Dock)에 입거해 10일간 정기 정비를 받는다.","eSum":"South Africa's Transnet National Port Authority has drydocked its largest vessel in over a decade, taking the 73,180-dwt tanker Troy into Durban's historic Prince Edward Graving Dock for 10 days of scheduled maintenance. The 1924-commissioned dock remains one of the largest in Africa.","kImp":"역내 대형선 수리·정비 인프라의 희소성을 보여주는 사례로, 기술팀의 드라이도킹 계획에 시사점을 준다.","eImp":"Highlights the scarcity of large-vessel drydock capacity in the region, relevant to technical teams' drydock planning.","url":"https://maritime-executive.com/article/south-africa-drydocks-largest-vessel-in-more-than-a-decade"},{"code":"TECH","title":"HD Hyundai launches first ship from revitalized Philippine shipyard","src":"Maritime Executive","date":"2026-07-29","kSum":"HD현대(HD Hyundai)가 옛 한진 수빅(Subic) 조선소를 인수해 재가동한 뒤 첫 신조선을 진수했다. 11만5000DWT 석유화학제품운반선 오리온제이드(Orion Jade)호가 7월29일 진수됐으며, 2019년 가동 중단된 야드의 부활을 알렸다.","eSum":"HD Hyundai launched its first newbuild from the revitalized former Hanjin shipyard at Subic Bay in the Philippines. The 115,000-dwt petrochemical tanker Orion Jade was launched on July 29, marking the restart of a yard that ceased operations in 2019.","kImp":"신흥 조선거점의 재가동은 글로벌 신조 감독·공급망 다변화 측면에서 주목된다.","eImp":"Reactivation of an emerging shipbuilding hub is notable for newbuild supervision and supply-chain diversification.","url":"https://maritime-executive.com/article/hd-hyundai-launches-first-ship-from-revitalized-philippine-shipyard"},{"code":"TECH","title":"Maersk Tankers and HD Hyundai Samho deliver first large ammonia carrier","src":"Maritime Executive","date":"2026-07-28","kSum":"머스크탱커스(Maersk Tankers)와 HD현대삼호(HD Hyundai Samho)가 첫 대형 암모니아운반선 제인머스크(Jane Maersk)호를 인도했다. 9만3000㎥급으로 액화암모니아와 LPG를 함께 운송하며, 오적재 방지를 위한 특수 '고위경보' 시스템 등 안전설비를 갖췄다.","eSum":"Maersk Tankers and HD Hyundai Samho delivered the first large ammonia carrier, Jane Maersk. The 93,000-cbm vessel can carry both liquefied ammonia and LPG and is fitted with advanced safety systems, including a specialized High Level Alarm to minimize misloading risks.","kImp":"차세대 대체연료 화물선의 인도로 기술팀의 암모니아 취급·안전관리 역량 요구가 커진다.","eImp":"Delivery of a next-generation alternative-fuel carrier raises technical demands for ammonia handling and safety management.","url":"https://maritime-executive.com/article/maersk-tankers-and-hd-hyundai-samho-celebrate-first-large-ammonia-carrier"},{"code":"TECH","title":"China sees 173% year-on-year surge in shipbuilding orders","src":"SAFETY4SEA","date":"2026-07-28","kSum":"중국 조선업 신규 수주가 전년 동기 대비 173% 급증한 것으로 나타났다. 신조 발주 회복세가 이어지며 중국 야드의 수주 잔량이 크게 늘고 있다.","eSum":"China recorded a 173% year-on-year surge in new shipbuilding orders, underscoring a strong rebound in newbuilding demand and a growing orderbook at Chinese yards.","kImp":"신조 시장 회복은 신조 감독·야드 슬롯 확보 계획에 직접적 영향을 준다.","eImp":"A newbuilding rebound directly affects newbuild supervision and yard-slot planning.","url":"https://safety4sea.com/china-sees-surge-of-173-surge-on-year-on-year-shipbuilding-orders"},{"code":"TECH","title":"China launches its largest hydrogen-powered inland cargo ship","src":"Maritime Executive","date":"2026-07-23","kSum":"중국이 최대 규모 수소연료 내륙 화물선 윈타오 1호(Yun Tao No. 1)를 진수했다. 광둥윈타오수소에너지(Guangdong Yuntao Hydrogen Energy)가 시스템을 개발했으며, 보조금 없이 상업운항이 가능한 표준화 선박 100척 네트워크 구축을 목표로 한다.","eSum":"China launched its largest hydrogen-powered inland cargo ship, Yun Tao No. 1, at Zhaoqing. Systems developer Guangdong Yuntao Hydrogen Energy plans a network of up to 100 standardized vessels aiming for commercial viability without subsidies.","kImp":"수소추진 상용선 확산은 기술팀의 신연료 기관·안전 검토 범위를 넓힌다.","eImp":"Scaling of hydrogen-fuelled commercial vessels widens technical scrutiny of novel propulsion and safety.","url":"https://maritime-executive.com/article/china-s-largest-hydrogen-powered-inland-cargo-ship-is-launched"}]},{"code":"HR","type":"news","kTitle":"Section 9. 해사 인사·선원","eTitle":"Section 9. Marine HR","items":[{"code":"HR","title":"NEMO project to examine how seafarer training must adapt for nuclear propulsion","src":"SAFETY4SEA","date":"2026-07-28","kSum":"니모(NEMO) 프로젝트가 원자력 추진 선박 도입에 대비해 선원 교육·훈련 체계를 어떻게 개편해야 하는지 검토한다. 신형 추진 방식에 필요한 역량과 자격 요건을 규명하는 것이 목표다.","eSum":"The NEMO project will examine how seafarer training and competency frameworks need to adapt for nuclear propulsion, identifying the skills and qualifications required for the new propulsion technology.","kImp":"미래 추진기술에 대비한 선원 역량 재설계 논의로, 인력·훈련 전략에 시사점을 준다.","eImp":"A forward look at reskilling seafarers for future propulsion, relevant to crewing and training strategy.","url":"https://safety4sea.com/nemo-to-examine-how-seafarer-training-needs-to-adapt-for-nuclear-propulsion"},{"code":"HR","title":"Career Paths: Anastasija Kuprijanova, Carbon Ridge","src":"SAFETY4SEA","date":"2026-07-27","kSum":"세이프티포씨(SAFETY4SEA) '커리어 패스' 인터뷰에서 카본리지(Carbon Ridge)의 아나스타시야 쿠프리야노바(Anastasija Kuprijanova)가 해운업 진로와 여성 인재의 경력 개발 경험을 공유했다.","eSum":"In SAFETY4SEA's Career Paths series, Anastasija Kuprijanova of Carbon Ridge shares her maritime career journey and reflections on professional development and diversity in shipping.","kImp":"인재 유치·유지와 다양성 제고 측면에서 해운 커리어 롤모델을 조명한다.","eImp":"Spotlights maritime career role models, relevant to talent attraction, retention and diversity.","url":"https://safety4sea.com/cm-career-paths-anastasija-kuprijanova-carbon-ridge"},{"code":"HR","title":"Seven micro-habits to help seafarers reset the mind","src":"SAFETY4SEA","date":"2026-07-23","kSum":"세이프티포씨(SAFETY4SEA)가 선원의 정신건강 관리를 위한 7가지 '마이크로 습관'을 제시했다. 승선 중 스트레스와 피로를 줄이고 마음을 재정비하는 실천적 방법을 다룬다.","eSum":"SAFETY4SEA outlines seven micro-habits to help seafarers reset their minds, offering practical ways to reduce onboard stress and fatigue and support mental wellbeing.","kImp":"선원 정신건강 관리의 실천적 지침으로 복지·유지율 제고에 기여한다.","eImp":"Practical mental-health guidance supporting seafarer welfare and retention.","url":"https://safety4sea.com/cm-7-micro-habits-to-help-reset-your-mind"},{"code":"HR","title":"Op-Ed: The maritime community can help fight sexual assault at sea","src":"Maritime Executive","date":"2026-07-27","kSum":"전 미국 해사청(MARAD) 수석법률고문 데니즈 크렙(Denise Krepp)이 해상 성폭력 대응을 촉구하는 기고를 냈다. 2019년 미 상선사관학교 실습생 성폭행 선장의 유죄가 7년 만에 확정된 사건을 계기로, 증거수집 참여·연방자금 회수·노조 제명 등 기소율 제고 방안을 제안했다.","eSum":"Former MARAD Chief Counsel Denise Krepp argues the maritime community must do more to fight sexual assault at sea, citing a captain's conviction seven years after a 2019 assault on a Merchant Marine Academy midshipman. She proposes crew evidence-gathering, withholding federal funds and union expulsion to raise prosecution rates.","kImp":"해상 성폭력 근절과 안전한 근무환경 조성이라는 선원 복지의 핵심 이슈를 제기한다.","eImp":"Raises a core seafarer-welfare issue: eliminating sexual assault and ensuring a safe workplace at sea.","url":"https://maritime-executive.com/editorials/op-ed-the-maritime-community-can-help-fight-sexual-assault-at-sea"},{"code":"HR","title":"Seafarer from stricken LPG carrier Gas Lisbon dies of his wounds","src":"Maritime Executive","date":"2026-07-23","kSum":"러시아 드론 공격으로 추정되는 화재를 입은 LPG운반선 가스리스본(Gas Lisbon)호의 부상 선원이 끝내 사망했다고 루마니아 당국이 밝혔다. 터키 선사 소속인 이 선박은 프로판 약 3800t을 싣고 우크라이나 레니(Reni)로 향하던 중 루마니아 앞바다 20해리에서 폭발을 보고했다.","eSum":"A seafarer injured in the fire aboard the LPG carrier Gas Lisbon has died of his wounds, Romanian authorities said. The Turkish-owned vessel, carrying about 3,800 tonnes of propane bound for Reni, Ukraine, reported an explosion some 20 nm off the Romanian coast after being likely struck by Russian drones.","kImp":"분쟁수역 통항에 따른 선원 인명 피해로, 안전한 승무·통항 결정의 중요성을 부각한다.","eImp":"A seafarer fatality from transit through a conflict zone, underscoring the stakes of crew safety and routing decisions.","url":"https://maritime-executive.com/article/sailor-aboard-lpg-carrier-gas-lisbon-dies-of-his-wounds"}]},{"code":"HSEQ","type":"news","kTitle":"Section 10. HSEQ (보건·안전·환경·품질)","eTitle":"Section 10. HSEQ","items":[{"code":"HSEQ","title":"UK MAIB: multiple errors contributed to crew member's death on bulk carrier","src":"Insurance Marine News","date":"2026-07-30","kSum":"영국 해양사고조사국(MAIB)이 2025년 10월14일 맨섬 선적 벌크선 월드프라이즈(World Prize)호에서 발생한 선원 실족 사망사고를 조사한 결과, 다수의 오류가 복합적으로 작용했다고 밝혔다.","eSum":"The UK MAIB found that a number of errors contributed to the death of a crew member who fell overboard from the Isle of Man-registered bulk carrier World Prize on 14 October 2025, according to its investigation report.","kImp":"인적·절차적 오류가 겹친 사망사고 교훈으로, 실족·추락 방지 관리의 재점검을 요구한다.","eImp":"Lessons from a fatality caused by compounding human and procedural errors, prompting review of fall-overboard controls.","url":"https://insurancemarinenews.com/insurance-marine-news/maib-finds-number-of-errors-contributed-to-death-of-crew-member/"},{"code":"HSEQ","title":"Tug captain pleads guilty over collision that killed three children","src":"SAFETY4SEA","date":"2026-07-28","kSum":"예인선 선장이 어린이 3명이 숨진 충돌사고와 관련해 유죄를 인정했다. 사고는 부주의한 견시와 조종 과실이 원인으로 지목됐다.","eSum":"A tugboat captain has pleaded guilty in connection with a collision that killed three children, in a case highlighting failures in lookout and navigational judgement.","kImp":"치명적 충돌사고의 형사책임 확정으로, 견시·당직 규율의 중요성을 재확인한다.","eImp":"Criminal accountability for a fatal collision reaffirms the importance of lookout and watchkeeping discipline.","url":"https://safety4sea.com/tugboat-captain-pleads-guilty-over-collision-that-killed-three-children"},{"code":"HSEQ","title":"Port of Tyne to close to clear damaged containership and collapsed crane","src":"Maritime Executive","date":"2026-07-30","kSum":"타인항(Port of Tyne)과 타인강 일부 구간이 7월30일 9시간 동안 폐쇄돼, 7월19일 발생한 접촉사고 수습이 진행된다. WTIV 윈드오르카(Wind Orca)호가 컨테이너선 BG오렌지(BG Orange)호를 들이받아 손상된 컨테이너와 붕괴된 갠트리크레인을 제거한다.","eSum":"The Port of Tyne and a section of the River Tyne will close for nine hours on July 30 to continue recovery from a July 19 allision, in which the WTIV Wind Orca struck the containership BG Orange, damaging containers and collapsing a gantry crane.","kImp":"항만 내 접촉사고의 대규모 수습으로, 작업선-상선 간 접근 관리 리스크를 부각한다.","eImp":"A major port allision cleanup highlights proximity-management risks between work vessels and merchant ships.","url":"https://maritime-executive.com/article/port-and-river-tyne-to-close-to-clear-damaged-containership-and-crane"},{"code":"HSEQ","title":"Portsmouth starts operating shore power system to lower emissions","src":"SAFETY4SEA","date":"2026-07-28","kSum":"영국 포츠머스(Portsmouth)항이 배출 저감을 위해 육상전력(shore power) 공급 시스템 가동을 시작했다. 접안 선박이 보조엔진 대신 육상전력을 사용해 대기오염과 온실가스를 줄인다.","eSum":"The Port of Portsmouth has begun operating a shore power system to cut emissions, allowing berthed ships to draw shore electricity instead of running auxiliary engines, reducing air pollution and greenhouse gases.","kImp":"항만 육상전력 확산은 접안 중 배출규제 대응과 환경 성능 향상에 기여한다.","eImp":"Wider port shore-power adoption supports at-berth emissions compliance and environmental performance.","url":"https://safety4sea.com/portsmouth-starts-operating-shore-power-system-to-lower-emissions"},{"code":"HSEQ","title":"Companies sign to advance shore power development in Rotterdam","src":"SAFETY4SEA","date":"2026-07-27","kSum":"로테르담(Rotterdam)항에서 여러 기업이 육상전력 인프라 개발을 진전시키기 위한 협약을 체결했다. 접안 선박의 배출 저감을 위한 육상전력 공급 확대가 목표다.","eSum":"Companies have signed an agreement to advance shore power development in the Port of Rotterdam, aiming to expand cold-ironing infrastructure to cut emissions from berthed vessels.","kImp":"주요 허브항의 육상전력 투자 확대는 접안 배출 저감 규제 흐름을 뒷받침한다.","eImp":"Expanded shore-power investment at a major hub reinforces the trend toward at-berth emissions reduction.","url":"https://safety4sea.com/companies-sign-to-advance-shore-power-development-in-rotterdam"},{"code":"HSEQ","title":"EU proposes first Indian ship recycling yards for approved list","src":"SAFETY4SEA","date":"2026-07-27","kSum":"유럽연합(EU)이 승인 재활용시설 목록에 인도 선박해체 야드를 처음으로 포함하는 방안을 제안했다. 홍콩협약(HKC) 기준 충족을 전제로 유럽 선박의 인도 내 친환경 해체 경로가 열릴 전망이다.","eSum":"The EU has proposed including Indian ship recycling yards on its list of approved facilities for the first time, potentially opening compliant, HKC-aligned recycling routes in India for EU-flagged ships.","kImp":"선박 재활용의 안전·환경 기준 준수 확대라는 측면에서 해체 관리에 영향을 준다.","eImp":"Advances safe, environmentally compliant ship recycling, affecting end-of-life vessel management.","url":"https://safety4sea.com/eu-proposes-first-indian-ship-recycling-yards-for-inclusion-on-approved-list"},{"code":"HSEQ","title":"Study warns EU ETS carbon cost recovery right may fail in practice","src":"SAFETY4SEA","date":"2026-07-27","kSum":"EU 배출권거래제(ETS)에서 선주가 용선자에게 탄소비용을 회수할 권리가 실제로는 작동하지 않을 수 있다는 연구가 발표됐다. 계약·정산 구조의 허점으로 비용 전가가 어려울 수 있다는 경고다.","eSum":"A study warns that shipowners' right to recover EU ETS carbon costs from charterers may fail in practice, citing contractual and settlement gaps that could leave owners unable to pass through the cost.","kImp":"탄소비용 배분의 불확실성은 규제 준수 부담과 상업적 리스크를 동시에 키운다.","eImp":"Uncertainty over carbon-cost allocation raises both compliance burden and commercial risk.","url":"https://safety4sea.com/study-warns-eu-ets-carbon-cost-recovery-right-may-fail-in-practice"}]},{"code":"KR","type":"news","kTitle":"Section 11. 한국 해운시장","eTitle":"Section 11. Korean Shipping","items":[{"code":"KR","title":"광양항 완전자동화 컨테이너부두 테스트베드 착공","src":"코리아쉬핑가제트","date":"2026-07-30","kSum":"해양수산부와 여수광양항만공사(YGPA)는 7월30일 광양항에서 국산 하역장비와 인공지능(AI) 기술을 적용한 완전자동화 컨테이너부두 조성을 위한 '항만자동화 테스트베드 구축사업' 착공식을 열었다. 2029년까지 국산 자동화 기술을 실증할 계획이다.","eSum":"Korea's Ministry of Oceans and Fisheries and Yeosu Gwangyang Port Authority (YGPA) broke ground on July 30 for a fully automated container terminal testbed at Gwangyang Port, using domestic cargo-handling equipment and AI, with demonstration planned through 2029.","kImp":"국산 항만자동화 기술 실증으로 한국 항만·물류 경쟁력 강화가 기대된다.","eImp":"Demonstrating homegrown port-automation technology aims to strengthen Korea's port and logistics competitiveness.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147733"},{"code":"KR","title":"KMI, 해운 연구기능 통합해 '해운정책·산업연구실' 신설","src":"코리아쉬핑가제트","date":"2026-07-30","kSum":"한국해양수산개발원(KMI)이 해운 분야 연구역량을 통합하고 정책 대응력을 강화하기 위해 해운물류·해사정책연구실과 해운산업연구실을 합친 '해운정책·산업연구실'을 신설한다.","eSum":"The Korea Maritime Institute (KMI) is establishing a new Shipping Policy and Industry Research Division by merging its shipping-logistics/maritime-policy and shipping-industry research units to consolidate research capacity and sharpen policy response.","kImp":"국책연구기관의 해운 연구 통합은 정책 지원 역량 강화로 이어진다.","eImp":"Consolidating shipping research at the state institute enhances policy-support capacity.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147732"},{"code":"KR","title":"묵암재단, 국립한국해양대에 발전기금 3억5000만원 기부","src":"코리아쉬핑가제트","date":"2026-07-29","kSum":"국립한국해양대학교는 7월29일 묵암재단으로부터 대학 발전기금 3억5000만원을 기부받았다고 밝혔다. 묵암재단은 한국 해운 현대화를 이끈 고(故) 박현규 고려해운(Korea Marine Transport, KMTC) 명예회장이 후학 양성을 위해 설립했다.","eSum":"Korea Maritime and Ocean University received a KRW 350 million development donation from the Mukam Foundation on July 29. The foundation was established by the late Park Hyun-kyu, honorary chairman of Korea Marine Transport (KMTC), a pioneer of Korean shipping modernization, to nurture future talent.","kImp":"해운 인재 양성 지원으로 국내 해운 교육 기반 강화에 기여한다.","eImp":"Supports maritime education, reinforcing Korea's talent pipeline for the shipping sector.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147727"},{"code":"KR","title":"삼성중공업, 2분기 영업이익 3250억원…전년 대비 대폭 개선","src":"코리아쉬핑가제트","date":"2026-07-24","kSum":"삼성중공업(Samsung Heavy Industries)은 2026년 2분기 매출액 3조2307억원, 영업이익 3250억원, 순이익 2228억원을 기록했다고 7월24일 밝혔다. 영업이익이 전년 대비 크게 늘며 실적 개선세가 뚜렷했다.","eSum":"Samsung Heavy Industries reported Q2 2026 revenue of KRW 3.23tn, operating profit of KRW 325bn and net profit of KRW 222.8bn on July 24, with operating profit sharply higher year-on-year.","kImp":"국내 조선 대형사의 실적 개선은 한국 조선업 호황을 재확인한다.","eImp":"Improved earnings at a major Korean shipbuilder confirm the strength of Korea's shipbuilding upcycle.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147679"},{"code":"KR","title":"팬스타그룹, 반도체 물량 호조에 한일 카페리 특수","src":"코리아쉬핑가제트","date":"2026-07-24","kSum":"한일 카페리선을 운항하는 국적선사 팬스타그룹(Pan Star Group)이 반도체 시장 활황에 따른 물동량 증가로 호조를 보이고 있다. 강상인 총괄사장은 AI발 반도체 수요로 관련 장비·소재 물량이 크게 늘었다고 밝혔다.","eSum":"Korean carrier Pan Star Group, which runs Korea-Japan car-ferry services, is benefiting from rising semiconductor-related cargo amid an AI-driven chip boom, with executives citing a strong increase in equipment and materials volumes.","kImp":"반도체 공급망 물류 수요 확대가 국적 카페리선사 실적을 견인한다.","eImp":"Growing semiconductor supply-chain logistics demand is boosting a Korean ferry operator's business.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147678"},{"code":"KR","title":"\"단순 자동화 넘어 해운 생산성 높이는 스마트항만 구축해야\"","src":"코리아쉬핑가제트","date":"2026-07-27","kSum":"피지컬 AI를 활용한 스마트항만 구축이 개별 장비 자동화를 넘어 항만·해운 네트워크 전체의 생산성을 높이는 방향으로 추진돼야 한다는 의견이 제기됐다. 전문가들은 기존 터미널의 완전자동화 전환 과제를 짚었다.","eSum":"Experts argued that smart-port development using physical AI should go beyond automating individual equipment to raising productivity across the entire port and shipping network, noting the challenges of fully automating existing terminals.","kImp":"스마트항만 논의가 장비 자동화에서 네트워크 생산성으로 확장되고 있다.","eImp":"The smart-port debate is broadening from equipment automation to network-wide productivity.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147692"},{"code":"KR","title":"극동MES, 상반기 경영전략회의서 물류환경 변화 대응 논의","src":"코리아쉬핑가제트","date":"2026-07-28","kSum":"해상 수출용 컨테이너 매매·임대 전문기업 극동MES(Kukdong MES)가 7월23~25일 중국 청두에서 2026년 상반기 경영전략회의를 열고 물류환경 변화 대응 방안을 논의했다. 대표이사와 해외 주요 임직원이 참석했다.","eSum":"Kukdong MES, a specialist in container trading and leasing for seaborne exports, held its H1 2026 management strategy meeting in Chengdu, China on July 23-25 to discuss responses to a shifting logistics environment, attended by its CEO and key overseas staff.","kImp":"국내 컨테이너 장비 기업의 전략 점검으로 물류 환경 변화 대응력을 강화한다.","eImp":"A Korean container-equipment firm's strategy review strengthens its response to logistics-market shifts.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147713"},{"code":"KR","title":"해양환경공단, AI 기반 해파리 폴립 탐지·관리 플랫폼 사업 추진","src":"코리아쉬핑가제트","date":"2026-07-29","kSum":"해양환경공단이 해양수산부·해양수산과학기술진흥원의 '해양수산 AI 응용제품 신속 상용화 지원 사업'에 최종 선정돼 'AI 기반 해파리 폴립 관리 플랫폼' 사업을 본격 추진한다. 국민 안전을 위한 해파리 대량 발생 사전 관리가 목표다.","eSum":"Korea Marine Environment Management Corporation was selected for a state program to fast-track commercialization of maritime AI products and will develop an AI-based jellyfish polyp management platform aimed at pre-empting large jellyfish blooms for public safety.","kImp":"해양 AI 응용 확대는 해양환경·안전 관리의 디지털 전환을 보여준다.","eImp":"Expanding maritime AI applications illustrates digital transformation in ocean environmental and safety management.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147721"},{"code":"KR","title":"한국선급, 3D프린팅(LW-DED) 적층제조 보수기술에 첫 제조법 인증","src":"코리아쉬핑가제트","date":"2026-07-28","kSum":"한국선급(KR)은 7월28일 대전 소재 에이엠솔루션즈에 레이저 와이어 직접에너지적층(LW-DED) 기반 적층제조 보수기술에 대한 제조법 인증서를 수여했다고 밝혔다. 금속 구조물의 손상 부위를 적층 방식으로 보수하는 기술의 안전성을 처음으로 인증한 사례다.","eSum":"Korean Register (KR) awarded its first manufacturing-process certification for a laser wire direct energy deposition (LW-DED) additive-manufacturing repair technology to AM Solutions in Daejeon on July 28, validating the safety of additively repairing damaged metal structures.","kImp":"선급의 적층제조 보수기술 인증은 신기술의 선박 적용 신뢰성을 높인다.","eImp":"Class certification of additive-manufacturing repair boosts confidence in applying the technology to ships.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147723"}]},{"code":"INS","type":"news","kTitle":"Section 12. 선체보험 (H&M)","eTitle":"Section 12. Marine Insurance (Hull & Machinery)","items":[{"code":"INS","title":"Explosion and fire aboard chemical tanker Bergstraum off south-east Norway","src":"Insurance Marine News","date":"2026-07-30","kSum":"화학·석유제품운반선 베르그스트라움(Bergstraum, IMO 9108740)호에서 7월28일 노르웨이 프레드릭스타(Fredrikstad) 앞 정박 중 폭발과 화재가 발생했다. 황산 화물의 유출 우려 속에 구조·소방 자원이 투입됐으며, 선체·기관 손상 규모가 주목된다.","eSum":"An explosion and fire broke out aboard the chemical/oil products tanker Bergstraum (IMO 9108740) on July 28 while at anchor off Fredrikstad, south-eastern Norway, amid concerns over its sulfuric acid cargo, drawing rescue and firefighting resources.","kImp":"선체·화물 손상 사고로 선체보험(H&M) 클레임 및 위험평가에 직접적 함의를 준다.","eImp":"A hull-and-cargo casualty with direct implications for hull & machinery (H&M) claims and risk assessment.","url":"https://insurancemarinenews.com/insurance-marine-news/explosion-and-fire-reported-aboard-chemical-tanker-off-south-east-norway/"},{"code":"INS","title":"Offshore vessel Skandi Amazonas declared a constructive total loss","src":"Insurance Marine News","date":"2026-07-30","kSum":"노르웨이 DOF그룹(DOF Group ASA)이 지원선 스칸디아마조나스(Skandi Amazonas, IMO 9528328)호를 좌초 이후 추정전손(CTL)으로 선언했다. 좌초로 인한 손상 규모가 커 수리보다 전손 처리가 선택됐다.","eSum":"Norway's DOF Group ASA has declared the offshore supply vessel Skandi Amazonas (IMO 9528328) a constructive total loss (CTL) following its grounding, with damage severe enough to warrant a total-loss settlement.","kImp":"추정전손 선언은 전형적 선체보험(H&M) 대형 클레임 사례로 시장에 영향을 준다.","eImp":"A CTL declaration is a classic large H&M claim with implications for the hull insurance market.","url":"https://insurancemarinenews.com/insurance-marine-news/skandi-amazonas-declared-a-ctl/"},{"code":"INS","title":"Maritime arbitration in numbers: London rebounds as Singapore and Hong Kong hold momentum","src":"Insurance Marine News","date":"2026-07-30","kSum":"법무법인 HFW의 제7판 '해사중재 통계(Maritime Arbitration in Numbers)' 보고서가 발표됐다. 런던이 반등하고 싱가포르·홍콩이 성장세를 유지하는 등 주요 중재지의 해사분쟁 처리 동향을 비교 분석했다.","eSum":"Law firm HFW released the seventh edition of its 'Maritime Arbitration in Numbers' report, providing a comparative analysis of dispute activity across key seats, with London rebounding while Singapore and Hong Kong maintain momentum.","kImp":"해사분쟁 처리 동향은 클레임·분쟁 해결 비용과 보험 리스크 평가에 영향을 준다.","eImp":"Trends in maritime dispute resolution affect claims/dispute costs and insurance risk assessment.","url":"https://insurancemarinenews.com/insurance-marine-news/maritime-arbitration-in-numbers-london-rebounds-as-singapore-and-hong-kong-maintain-momentum/"},{"code":"INS","title":"Marine insurers may ban payments to Iran for Hormuz transits","src":"Maritime Executive","date":"2026-07-23","kSum":"로이즈시장협회(LMA)가 호르무즈해협 통항 보험에 삽입 가능한 선택적 조항을 마련했다. 선주가 이란에 통항료를 지불한 사실이 드러나면 보험자가 담보를 취소할 수 있도록 해 제재 리스크를 차단한다. 걸프 전쟁위험 보험료는 선체가액의 3%에서 최근 5% 이상으로 상승했다.","eSum":"The Lloyd's Market Association has created an optional clause for Strait of Hormuz cover allowing insurers to cancel policies if an owner is found to have paid a toll to Iran, guarding against sanctions risk. Gulf war-risk premiums have risen from 3% of hull value toward 5% or more.","kImp":"선체·전쟁위험 담보 조건 강화와 보험료 급등으로 통항 경제성이 크게 흔들린다.","eImp":"Tightened hull/war-risk terms and surging premiums materially affect the economics of transiting the strait.","url":"https://maritime-executive.com/article/marine-insurers-may-ban-payments-to-iran-for-hormuz-transits"},{"code":"INS","title":"U.S. sanctions two 'insurers' handling Iran's Hormuz transit fees","src":"Maritime Executive","date":"2026-07-29","kSum":"미국 재무부가 호르무즈해협 통항료 구조를 뒷받침하는 두 기업, 페르시안걸프해양보험(Persian Gulf Marine Insurance Company)과 호르무즈세이프(HormuzSafe Marine Services Authority)를 제재 대상에 올렸다. 이들 기업이 이란 혁명수비대(IRGC)의 '보험' 사업 중심에 있다고 판단했다.","eSum":"The U.S. Treasury sanctioned two companies, the Persian Gulf Marine Insurance Company and HormuzSafe Marine Services Authority, which it says are central to the IRGC's 'insurance' scheme underpinning Iran's Strait of Hormuz transit-fee structure.","kImp":"제재 확대는 해상보험·통항 결제의 컴플라이언스 리스크를 한층 키운다.","eImp":"Expanded sanctions further heighten compliance risk around marine insurance and transit payments.","url":"https://maritime-executive.com/article/u-s-sanctions-two-insurers-for-handling-iran-s-hormuz-transit-fees"}]},{"code":"PNI","type":"news","kTitle":"Section 13. P&I 클럽","eTitle":"Section 13. P&I Clubs","items":[{"code":"PNI","title":"UK P&I: India restrictions on satellite phones and satellite communication equipment","src":"UK P&I Club","date":"2026-07-30","kSum":"UK P&I 클럽이 인도의 위성전화·위성통신장비 관련 규제를 회원사에 안내했다. 인도 항만 기항·통항 시 위성통신 장비 관련 절차와 위반 리스크에 유의할 것을 권고했다.","eSum":"The UK P&I Club advised members on India's restrictions on satellite phones and satellite communication equipment, urging caution over procedures and enforcement risks for vessels calling at or transiting Indian waters.","kImp":"회원사 대상 규제 안내로 인도 기항 시 통신장비 관련 컴플라이언스 리스크를 예방한다.","eImp":"A member advisory helping prevent compliance risk around communications equipment when calling India.","url":"https://www.ukpandi.com/news-and-resources/news/article/india-restrictions-on-satellite-phones-and-satellite-communication-equipment/"},{"code":"PNI","title":"UK P&I: methanol - alternative fuel spill response considerations","src":"UK P&I Club","date":"2026-07-23","kSum":"UK P&I 클럽이 대체연료 메탄올의 누출 대응 시 고려사항을 정리한 손실예방 자료를 발표했다. 메탄올 특성에 맞는 방재·대응 절차와 안전관리 요점을 다룬다.","eSum":"The UK P&I Club published loss-prevention guidance on spill response considerations for methanol as an alternative fuel, covering response procedures and safety-management points tailored to methanol's properties.","kImp":"대체연료 확산에 대응한 방재 지침으로 P&I 손실예방 역량을 강화한다.","eImp":"Spill-response guidance for a growing alternative fuel strengthens P&I loss prevention.","url":"https://www.ukpandi.com/news-and-resources/news/article/methanol-alternative-fuel-spill-response-considerations/"},{"code":"PNI","title":"UK P&I: ammonia - alternative fuel spill response considerations","src":"UK P&I Club","date":"2026-07-28","kSum":"UK P&I 클럽이 독성·부식성이 강한 대체연료 암모니아의 누출 대응 고려사항을 담은 손실예방 자료를 내놨다. 암모니아 취급·비상대응 시 인명 보호와 방재 절차를 강조한다.","eSum":"The UK P&I Club issued loss-prevention guidance on spill response considerations for ammonia as an alternative fuel, emphasizing personnel protection and response procedures given ammonia's toxic and corrosive properties.","kImp":"암모니아 연료 도입에 대비한 P&I 방재 지침으로 사고·클레임 예방에 기여한다.","eImp":"P&I response guidance for ammonia fuel helps prevent incidents and claims.","url":"https://www.ukpandi.com/news-and-resources/news/article/ammonia-alternative-fuel-spill-response-considerations/"},{"code":"PNI","title":"UK P&I 'Inside Ship: Blackouts' safety training released","src":"UK P&I Club","date":"2026-07-30","kSum":"UK P&I 클럽이 선내 정전(blackout) 상황을 다룬 안전교육 콘텐츠 'Inside Ship: Blackouts'를 공개했다. 정전 예방·대응 절차와 기관 관리 요점을 선원 교육용으로 제시한다.","eSum":"The UK P&I Club released 'Inside Ship: Blackouts', a safety-training resource addressing onboard blackout scenarios, prevention and response procedures, and key engineering-management points for crew training.","kImp":"정전 대비 선원 교육 자료로 기관 사고·클레임 예방을 지원한다.","eImp":"A crew-training resource on blackouts supporting prevention of machinery incidents and claims.","url":"https://www.ukpandi.com/news-and-resources/safety-advice-training/article/inside-ship-blackouts/"},{"code":"PNI","title":"West of England P&I awarded S&P 'A-' (stable) rating","src":"코리아쉬핑가제트","date":"2026-07-27","kSum":"영국 해상보험사 웨스트오브잉글랜드(West of England) P&I가 재무성과 개선을 바탕으로 국제신용평가사 S&P글로벌로부터 신용등급 A-(안정적)를 받았다고 밝혔다. S&P는 웨스트P&I가 최근 수년간 여러 지표에서 개선을 이뤘다고 평가했다.","eSum":"West of England P&I has been assigned an 'A-' (stable) credit rating by S&P Global on the back of improved financial performance, with S&P noting the club's progress across several metrics in recent years.","kImp":"P&I 클럽의 신용등급 상향은 회원사에 대한 재무 안정성 신뢰를 높인다.","eImp":"An improved P&I club rating enhances confidence in the club's financial stability for members.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147702"}]},{"code":"VET","type":"news","kTitle":"Section 14. 베팅","eTitle":"Section 14. Vetting","items":[{"code":"VET","title":"RightShip and NorthStandard collaborate to reduce duplicate inspections","src":"Maritime Executive","date":"2026-07-29","kSum":"안전·리스크 인텔리전스 플랫폼 라이트십(RightShip)과 주요 P&I 클럽 노스스탠다드(NorthStandard)가 중복 검사를 줄이기 위한 전략적 협력을 발표했다. 노스스탠다드가 라이트십의 안전한 검사보고서 공유 기능을 통해 기존 검사 데이터를 활용함으로써 불필요한 중복 검사를 줄이고 손실예방을 강화한다. 드라이벌크 선박관리사 오리온리더라이(Orion Reederei)가 운영모델 검증에 참여했다.","eSum":"RightShip and P&I club NorthStandard announced a strategic collaboration to reduce duplicate inspections, with NorthStandard using RightShip's secure inspection-report sharing to reuse existing inspection data, cut unnecessary duplicate surveys and strengthen loss prevention. Dry-bulk manager Orion Reederei helped test the operating model.","kImp":"검사보고서 공유로 중복 검사 부담을 줄여 선원·선사의 검사 피로를 완화하고 베팅 효율을 높인다.","eImp":"Sharing inspection reports reduces duplicate-inspection burden, easing crew/owner assurance fatigue and improving vetting efficiency.","url":"https://maritime-executive.com/corporate/rightship-and-northstandard-collaborate-to-reduce-duplicate-inspections"},{"code":"VET","title":"IMO advances harmonized PSC inspections and officer training","src":"SAFETY4SEA","date":"2026-07-28","kSum":"국제해사기구(IMO)가 항만국통제(PSC) 검사의 조화(harmonization)와 검사관 교육 강화를 진전시켰다. 검사 기준의 일관성 제고와 검사관 역량 표준화를 통해 검사 품질을 높이는 것이 목표다.","eSum":"The IMO advanced work on harmonizing port state control (PSC) inspections and strengthening officer training, aiming to improve consistency of inspection standards and standardize inspector competency to raise inspection quality.","kImp":"PSC 검사 조화와 검사관 교육 강화는 선박 베팅·검사 결과의 일관성과 신뢰성을 높인다.","eImp":"Harmonized PSC inspections and better inspector training improve the consistency and reliability of vessel vetting and inspection outcomes.","url":"https://safety4sea.com/cm-imo-advances-harmonized-psc-inspections-and-officer-training"}]},{"code":"CLASS","type":"news","kTitle":"Section 15. 선급","eTitle":"Section 15. Classification","items":[{"code":"CLASS","title":"Bureau Veritas grants AiP to Seatrium's 30MW floating data centre concept","src":"marinelink","date":"2026-07-28","kSum":"뷰로베리타스(Bureau Veritas)가 시트리움(Seatrium)의 30MW급 부유식 데이터센터(FDC) 콘셉트에 원칙승인(AiP)을 부여했다. 이 콘셉트는 잔교 계류식 무추진 바지선에 5MW 규모의 '데이터 인 어 박스' 모듈 6기를 탑재하고 자연 해수 냉각을 활용한다. 시트리움은 100MW 이상 하이퍼스케일 설계도 개발 중이라고 밝혔다.","eSum":"Bureau Veritas Marine & Offshore has granted Approval in Principle to Seatrium's 30 MW Floating Data Centre concept, a jetty-moored non-propelled barge carrying six 5 MW Data-In-A-Box modules with natural seawater cooling. BV independently assessed the concept's technical feasibility, and Seatrium said it is also developing 100 MW-plus hyperscale designs.","kImp":"AI·클라우드 수요 급증에 따른 해상 디지털 인프라라는 새로운 선급 영역을 보여준다.","eImp":"Signals a new classification frontier as offshore digital infrastructure emerges to meet surging AI and cloud demand.","url":"https://www.marinelink.com/news/bureau-veritas-gives-blessing-seatriums-541582"},{"code":"CLASS","title":"Nuclear-ship designs clear three class AiPs but remain far from service","src":"gcaptain","date":"2026-07-27","kSum":"2026년 6월 이후 원자력 상선 콘셉트 3건이 선급 원칙승인(AiP)을 받았다. 한국 컨소시엄의 용융염원자로(MSR) 컨테이너선(ABS), 로이드선급(Lloyd's Register)이 지원한 카캐리어, MIT 해양컨소시엄 원자로 설계가 대상이다. gCaptain은 AiP가 건조·운항 인가가 아니며 1981년 IMO 원자력선 코드가 신형 원자로에 미비하다는 점을 지적했다.","eSum":"Three nuclear-powered commercial ship concepts have received class AiPs since June 2026: a Korean consortium's molten-salt reactor containership (ABS), a Lloyd's Register-backed car carrier, and a reactor from the MIT Maritime Consortium. gCaptain notes an AiP is not a build or operating permit and that the 1981 IMO nuclear-ship code is decades out of date for these reactor types.","kImp":"선급들이 원자력 추진의 기술적 타당성은 인정하나 규제·보험·기항 협정이라는 큰 장벽이 남아 있음을 보여준다.","eImp":"Class societies now accept nuclear propulsion may be technically feasible, but regulatory, insurance and port-access hurdles remain formidable.","url":"https://gcaptain.com/nuclear-ships-just-cleared-three-design-reviews-but-theyre-potentially-decades-from-trading-port-to-port/"},{"code":"CLASS","title":"ABS deepens South Korea-US shipbuilding collaboration on software-defined vessels","src":"marinelink","date":"2026-07-24","kSum":"ABS가 한국 조선·해양 연구기관들과 소프트웨어 정의 선박(software-defined vessel) 기술을 진전시키기 위한 두 건의 협약에 서명했다. 협약에 따라 KRISO(선박해양플랜트연구소)는 첨단 선박공학·스마트 제조·연구 역량을, ABS는 선급·인증·검증·해사안전·규제 프레임워크 관련 지침을 제공한다.","eSum":"ABS has signed two agreements with South Korean shipbuilding organizations to advance software-defined vessel technology. Under the deals KRISO will contribute advanced ship engineering, smart manufacturing and research, while ABS provides guidance on classification, certification, verification, maritime safety and regulatory frameworks.","kImp":"미국 선급과 한국 조선 R&D의 협력 강화로 차세대 디지털 선박 표준 주도권 경쟁이 심화된다.","eImp":"Tightens US class-Korean shipbuilding R&D ties in the race to set next-generation digital vessel standards.","url":"https://www.marinelink.com/news/abs-deepens-south-koreaus-shipbuilding-541510"},{"code":"CLASS","title":"ABS awards AiP to Korean SMR-powered 15,000 TEU containership concept","src":"safety4sea","date":"2026-07-23","kSum":"ABS가 한국원자력연구원(KAERI)·선박해양플랜트연구소(KRISO)·삼성중공업(Samsung Heavy Industries)과 공동 개발한 원자력추진 15,000TEU 컨테이너선 콘셉트에 원칙승인(AiP)을 부여했다. 이 선박은 용융염원자로(MSR) 기반 소형모듈원자로(SMR) 2기를 탑재하며, 한국의 'K-Moonshot' 연구 프로그램의 일환이다.","eSum":"ABS has granted Approval in Principle for a nuclear-powered 15,000 TEU containership concept co-developed with KAERI, KRISO and Samsung Heavy Industries. The design carries two molten-salt-reactor small modular reactors (MARINA) and sits under South Korea's state-backed 'K-Moonshot' research programme.","kImp":"한국이 상선용 원자력추진 설계에서 선두권 진입을 노리고 있음을 상징한다.","eImp":"Marks South Korea's push to the front of commercial nuclear-propulsion ship design.","url":"https://safety4sea.com/nuclear-powered-container-ship-design-receives-approval-from-abs/"}]},{"code":"COMM","type":"news","kTitle":"Section 16. 상업·시황","eTitle":"Section 16. Commercial & Markets","items":[{"code":"COMM","title":"Sallaum Lines orders 8,600 CEU LNG dual-fuel PCTC from China Merchants Jinling","src":"marinelink","date":"2026-07-28","kSum":"스위스 살라움라인스(Sallaum Lines)가 중국 초상국진링조선소(China Merchants Jinling)에 8,600CEU급 자동차운반선(PCTC) 1척을 발주했다. LNG 이중연료·암모니아 대응 사양으로 전장 199.99m, 폭 38m이며 기존 선박보다 최대 1,100대 더 실을 수 있다. 인도는 2029년 예정이다.","eSum":"Swiss operator Sallaum Lines has ordered an 8,600 CEU pure car and truck carrier from China Merchants Jinling Shipyard. The LNG dual-fuel, ammonia-ready vessel is 199.99 m long with a 38 m beam and can carry up to 1,100 more vehicles than its predecessors, with delivery scheduled for 2029.","kImp":"PCTC 신조 붐이 이어지며 중형 선사들도 친환경 선대를 공격적으로 확대하고 있다.","eImp":"Shows the PCTC newbuilding boom extending to mid-sized operators aggressively greening their fleets.","url":"https://www.marinelink.com/news/sallaum-lines-orders-lng-dualfuel-pctc-541616"},{"code":"COMM","title":"China vehicle-export boom keeps lifting PCTC charter rates and asset values","src":"lloydslist","date":"2026-07-28","kSum":"중국의 차량 수출 급증이 자동차운반선(PCTC) 용선료와 중고선가, 신조 발주를 동시에 밀어올리고 있다고 로이드리스트(Lloyd's List)가 전했다. 6,500CEU급 1년 정기용선 지수는 연초 대비 약 45% 오른 하루 약 6만7천 달러에 이르렀다. 중국은 6월 말까지 이미 500만 대 이상을 수출했다.","eSum":"China's surging vehicle exports continue to push PCTC charter rates, secondhand values and newbuilding orders higher, Lloyd's List reports. The one-year time-charter index for a 6,500 CEU car carrier has risen about 45% since the start of 2026 to roughly $67,000/day, with China having already exported over five million vehicles by end-June.","kImp":"홍해 우회로 인한 톤·마일 증가와 중국 수출 호조가 겹쳐 자동차선 시황이 강세를 유지한다.","eImp":"Red Sea diversions plus booming Chinese exports keep the car-carrier market exceptionally tight.","url":"https://www.lloydslist.com/LL1157957/Chinas-continued-vehicle-export-boom-boosts-PCTC-charter-rates-asset-values-and-newbuild-orders"},{"code":"COMM","title":"26-year-old PCTC fetches about $42m, underscoring tight vehicle-carrier market","src":"xindemarinenews","date":"2026-07-28","kSum":"선령 26년의 노후 자동차운반선(PCTC)이 약 4,200만 달러에 매각되며 강한 시황을 방증했다. MSC 계열의 GCC도 관심을 보인 것으로 전해졌다. 노후선까지 이례적으로 높은 가격에 거래되는 것은 현재 차량 운송 시장의 강세를 보여준다.","eSum":"A 26-year-old pure car and truck carrier has reportedly sold for around $42 million, an unusually strong price for aged tonnage, with MSC-owned GCC also said to have shown interest. Even vintage vessels commanding premium prices highlights the strength of today's vehicle-shipping market.","kImp":"노후 PCTC 자산가치 급등은 신조 인도 전까지 선복 부족이 이어질 것임을 시사한다.","eImp":"Soaring values for old PCTCs point to persistent capacity shortage until newbuild deliveries arrive.","url":"https://www.xindemarinenews.com/news/2081655940798779393"},{"code":"COMM","title":"Capesize slump drags Baltic Dry Index to multi-week low","src":"bairdmaritime","date":"2026-07-28","kSum":"케이프사이즈 운임 급락으로 발틱건화물지수(BDI)가 약 2,752로 다주 만의 최저치로 밀렸다. 케이프사이즈 지수는 주간 기준 약 12% 하락했고 하루 평균 수익은 약 3만3천~3만4천 달러 수준으로 떨어졌다. 파나막스 등 중형선도 약세를 보였다.","eSum":"A slump in Capesize rates pushed the Baltic Dry Index down to a multi-week low around 2,752, with the Capesize index off nearly 12% on the week and average daily earnings sliding to roughly $33,000-$34,000. Panamax and smaller segments also softened.","kImp":"철광석·석탄 수요 둔화 신호로 하반기 건화물 시황 조정 가능성이 부각된다.","eImp":"Softer iron ore and coal demand signals raise the prospect of a dry-bulk correction into H2.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/bulkers/capesize-rate-slump-spoils-week-for-baltic-dry-bulk-index"},{"code":"COMM","title":"Drewry World Container Index eases to about $4,374 as East-West rates soften","src":"drewry","date":"2026-07-23","kSum":"드류리(Drewry) 세계컨테이너지수(WCI)가 40피트 컨테이너당 약 4,374달러로 4% 하락했다. 아시아-유럽 및 태평양횡단 노선 운임이 2주 연속 내리며 선복 증가와 수요 둔화가 겹친 결과다. 다만 호르무즈 해협 우려로 일부 선사는 8월부터 긴급유류할증료(EFS)를 예고했다.","eSum":"Drewry's World Container Index eased 4% to about $4,374 per 40ft box as Asia-Europe and Transpacific rates fell for a second straight week amid added capacity and easing demand. However, several carriers announced Emergency Fuel Surcharges effective August 2026 citing Strait of Hormuz concerns.","kImp":"기저 운임은 약세이나 지정학 리스크발 할증료가 화주 비용을 다시 끌어올릴 수 있다.","eImp":"Underlying rates are softening, but geopolitics-driven surcharges could lift shipper costs again.","url":"https://www.drewry.co.uk/supply-chain-advisors/supply-chain-expertise/world-container-index-assessed-by-drewry"},{"code":"COMM","title":"Crude tanker ordering hits record as VLCC resales command steep premiums","src":"splash247","date":"2026-07-28","kSum":"2026년 원유운반선 신조 계약이 234척·6,000만 DWT로 사상 최대를 기록했으며, 그중 VLCC가 151척으로 지난해 전체의 두 배를 넘었다고 스플래시(Splash247)가 전했다. 신조 VLCC가 약 1억3,200만 달러인 반면 리세일선은 약 1억7,200만 달러에 거래돼 즉시 인도 선복에 프리미엄이 붙고 있다.","eSum":"Crude tanker contracting has reached a record 234 ships and 60m dwt in 2026, led by 151 VLCCs — more than double the whole of 2025, Splash247 reports. A newbuild VLCC is priced around $132m while resales command about $172m, reflecting the premium on near-term availability.","kImp":"제재·우회 항로에 따른 톤·마일 수요가 유조선 발주와 자산가치를 동시에 밀어올리고 있다.","eImp":"Sanctions and reroute-driven tonne-mile demand are simultaneously fueling tanker orders and asset values.","url":"https://splash247.com/crude-tanker-orders-hit-record-high/"}]},{"code":"GEO","type":"news","kTitle":"Section 17. 지정학","eTitle":"Section 17. Geopolitics","items":[{"code":"GEO","title":"EU agrees member states may sell confiscated Russian shadow-fleet oil cargoes","src":"thedefensepost","date":"2026-07-28","kSum":"EU가 제재 회피 혐의 선박에서 압류한 러시아산 원유 등 화물을 회원국이 매각할 수 있도록 합의했다. 이는 EU 21차 제재 패키지의 일환으로, 이른바 '그림자 선단(shadow fleet)'이 운송하는 화물에 적용된다. 압류 화물 처분 프레임워크로 제재 이행이 한층 강화된다.","eSum":"The EU has agreed to let member states sell Russian oil and other cargoes confiscated from vessels suspected of circumventing sanctions. Part of the bloc's 21st sanctions package, the measure applies to cargoes carried by Russia's so-called shadow fleet, creating a framework to dispose of seized cargo.","kImp":"화물 압류·매각 권한 도입으로 그림자 선단에 대한 유럽의 실질적 압박 수단이 커진다.","eImp":"A cargo seizure-and-sale mechanism sharpens Europe's practical leverage over the shadow fleet.","url":"https://thedefensepost.com/2026/07/28/eu-russia-oil-shadow-fleet/"},{"code":"GEO","title":"EU naval force boards sanctioned shadow-fleet tanker over suspected false flag","src":"gcaptain","date":"2026-07-28","kSum":"EU 이리니 작전(Operation IRINI) 소속 함정이 러시아 그림자 선단과 연계된 유조선 '사우스 스타(South Star)'에 승선해 선적국 확인 검사를 실시했다. 해당 선박은 러시아산 석유·석유제품을 불규칙·고위험 방식으로 운송한 혐의로 EU 제재 대상이다.","eSum":"Forces assigned to the EU's Operation IRINI boarded the oil tanker South Star for a flag-verification inspection amid a suspected false flag. The vessel is under EU sanctions over its alleged role in transporting Russian oil and petroleum products using irregular, high-risk shipping practices.","kImp":"유럽 해군의 그림자 선단 승선·검문이 상시화되며 회피 선단의 운항 리스크가 커진다.","eImp":"Routine European naval boardings raise the operational risk for evasion-fleet tankers.","url":"https://gcaptain.com/eu-naval-force-boards-sanctioned-russian-shadow-fleet-tanker-over-suspected-false-flag/"},{"code":"GEO","title":"Houthis weigh imposing transit fees on Red Sea and Bab el-Mandeb shipping","src":"insurancejournal","date":"2026-07-29","kSum":"예멘 후티(Houthi)가 이란의 호르무즈 통행료 방식을 본떠 홍해와 바브엘만데브(Bab el-Mandeb) 해협을 지나는 대부분 선박에 통행료를 부과하는 방안을 검토 중인 것으로 전해졌다. 후티 관계자들이 이란 방문 중 이 사안을 논의했으며, 도입 시점은 아직 제시되지 않았다.","eSum":"Yemen's Houthis are reportedly considering imposing fees on most traffic through the Red Sea and the narrow Bab el-Mandeb gateway, echoing Iran's Hormuz playbook. Houthi officials discussed the idea with Iranian counterparts during a visit to Tehran, though no timeframe for implementation was given.","kImp":"제2의 초크포인트에 통행료가 도입되면 홍해 우회 비용과 공급망 리스크가 추가로 커진다.","eImp":"A toll on a second chokepoint would add fresh cost and supply-chain risk on top of Red Sea diversions.","url":"https://www.insurancejournal.com/news/international/2026/07/29/879298.htm"},{"code":"GEO","title":"Chinese supertankers exit Red Sea via Bab el-Mandeb amid Houthi threats","src":"marinelink","date":"2026-07-23","kSum":"사우디산 원유 총 400만 배럴을 실은 중국 초대형 유조선 2척이 후티 위협 속에 바브엘만데브 해협을 통해 홍해를 빠져나가고 있는 것으로 파악됐다. 중국·인도가 러시아·중동산 원유의 핵심 구매처인 가운데, 후티의 위협 확대가 주요 원유 항로에 직접 영향을 주고 있다.","eSum":"Two Chinese supertankers carrying a combined 4 million barrels of Saudi Arabian oil are exiting the Red Sea via the Bab el-Mandeb strait amid Houthi threats. With China and India key buyers of Russian and Middle East crude, the expanding Houthi threat is directly affecting major crude routes.","kImp":"주요 원유 항로에서 실제 선박 이동 변화로 홍해 리스크가 시황에 반영되고 있음을 보여준다.","eImp":"Concrete vessel movements show Red Sea risk feeding directly into crude-trade routing.","url":"https://www.marinelink.com/news/chinese-supertankers-exiting-red-sea-amid-541456"},{"code":"GEO","title":"EU's 21st package adds 218 designations, targets shadow-fleet refuelling vessels","src":"techtimes","date":"2026-07-23","kSum":"EU가 21차 대러 제재 패키지에서 218건의 신규 지정을 단행하며 처음으로 그림자 선단 유조선에 해상 급유하는 선박까지 겨냥했다. 아울러 러시아산 원유 가격상한을 배럴당 44.10달러로 동결했다. 제재 대상이 급유 지원 선박으로 확대되며 회피망 압박이 강화된다.","eSum":"The EU's 21st sanctions package reached 218 new designations and, for the first time, targets vessels that refuel Russia's shadow-fleet tankers at sea, while freezing the Russian oil price cap at $44.10 per barrel. Extending sanctions to bunkering-support ships tightens pressure on the evasion network.","kImp":"급유 지원 선박까지 제재망에 포함되며 그림자 선단의 운영 비용과 리스크가 상승한다.","eImp":"Pulling refuelling ships into the net raises operating costs and risk across the shadow fleet.","url":"https://www.techtimes.com/articles/321441/20260723/eu-passes-218-russia-sanctions-targets-vessels-that-refuel-shadow-fleet-tankers.htm"}]},{"code":"TW","type":"news","kTitle":"Section 18. 트레이드윈즈","eTitle":"Section 18. TradeWinds","items":[{"code":"TW","title":"US urged to launch public container shipping line to counter foreign carrier dominance","src":"tradewindsnews","date":"2026-07-29","kSum":"미국이 외국 선사의 지배력에 맞서 공공 컨테이너 선사를 설립해야 한다는 주장이 제기됐다고 트레이드윈즈(TradeWinds)가 전했다.","eSum":"TradeWinds reports calls for the US to launch a public container shipping line to counter the dominance of foreign carriers.","kImp":"미국 해운 자립 논쟁이 컨테이너 정기선 분야로 확산되고 있다.","eImp":"The US maritime self-reliance debate is spreading into liner shipping.","url":"https://www.tradewindsnews.com/containers/us-urged-to-launch-public-container-shipping-line-to-counter-foreign-carrier-dominance/2-1-2022069"},{"code":"TW","title":"Ardmore Shipping notches earnings beat with record tanker rates and dividend","src":"tradewindsnews","date":"2026-07-29","kSum":"아드모어쉬핑(Ardmore Shipping)이 기록적인 유조선 운임에 힘입어 시장 예상을 웃도는 실적과 배당을 발표했다고 트레이드윈즈가 전했다.","eSum":"TradeWinds reports Ardmore Shipping beat earnings expectations on record tanker rates and declared a dividend.","kImp":"제품유조선 시황 강세가 상장 탱커 선사 실적으로 확인되고 있다.","eImp":"Strong product-tanker markets are showing through in listed tanker owners' results.","url":"https://www.tradewindsnews.com/finance/ardmore-shipping-notches-earnings-beat-with-record-tanker-rates-and-dividend/2-1-2022400"},{"code":"TW","title":"The theft on land that's concerning shipping lines","src":"tradewindsnews","date":"2026-07-29","kSum":"육상에서의 화물 절도가 정기선사들의 새로운 우려로 부상하고 있다고 트레이드윈즈가 진단했다.","eSum":"TradeWinds examines how cargo theft on land is emerging as a growing concern for shipping lines.","kImp":"해상뿐 아니라 육상 물류 보안이 공급망 리스크로 확대되고 있다.","eImp":"Supply-chain risk is widening beyond the sea to landside logistics security.","url":"https://www.tradewindsnews.com/opinion/the-theft-on-land-that-s-concerning-shipping-lines/2-1-2022479"},{"code":"TW","title":"Samudera Shipping Line profit falls 20% as costs outpace revenue","src":"tradewindsnews","date":"2026-07-29","kSum":"사무데라쉬핑라인(Samudera Shipping Line)의 이익이 비용 상승이 매출 증가를 앞지르며 20% 감소했다고 트레이드윈즈가 전했다.","eSum":"TradeWinds reports Samudera Shipping Line's profit fell 20% as rising costs outpaced revenue growth.","kImp":"아시아 역내 컨테이너 선사들이 비용 압박에 직면하고 있음을 보여준다.","eImp":"Shows intra-Asia container carriers facing mounting cost pressure.","url":"https://www.tradewindsnews.com/containers/samudera-shipping-line-profit-falls-20-as-rising-costs-outpace-revenue-growth/2-1-2022456"},{"code":"TW","title":"Greek tankers ship out Iraqi fuel trucked to the Mediterranean","src":"tradewindsnews","date":"2026-07-27","kSum":"그리스 유조선들이 육상 트럭으로 지중해까지 운반된 이라크산 연료를 실어 나르고 있다고 트레이드윈즈가 전했다. 호르무즈 우회 물류가 새로운 운송 패턴을 만들어내고 있다.","eSum":"TradeWinds reports Greek tankers are loading Iraqi fuel that was transported overland by truck to the Mediterranean, an adaptation to Hormuz-area disruption.","kImp":"호르무즈 위기가 원유·연료의 육상 우회라는 이례적 물류를 촉발하고 있다.","eImp":"The Hormuz crisis is spawning unusual overland workarounds for fuel movement.","url":"https://www.tradewindsnews.com/tankers/greek-tankers-ship-out-iraqi-fuel-transported-to-mediterranean-by-truck/2-1-2021190"},{"code":"TW","title":"US-listed shipping stocks thriving as Middle East conflict expands","src":"tradewindsnews","date":"2026-07-23","kSum":"중동 분쟁 확대 속에 미국 상장 해운주가 강세를 보이고 있다고 트레이드윈즈가 전했다. 운임 급등 기대가 투자심리를 끌어올리고 있다.","eSum":"TradeWinds reports US-listed shipping stocks are thriving as the Middle East conflict expands, with expectations of surging rates lifting sentiment.","kImp":"지정학 리스크가 해운주에는 단기 호재로 작용하는 역설적 상황이 이어진다.","eImp":"Geopolitical risk is paradoxically acting as a near-term tailwind for shipping equities.","url":"https://www.tradewindsnews.com/finance/us-listed-shipping-stocks-thriving-as-middle-east-conflict-expands/2-1-2020381"}]},{"code":"HOT","type":"news","kTitle":"Section 19. 호르무즈 해협 위기","eTitle":"Section 19. Strait of Hormuz Crisis","items":[{"code":"HOT","title":"Oman proposes Gulf-backed voluntary Hormuz transit fee plan; Iran rejects joint management","src":"marinelink","date":"2026-07-28","kSum":"오만(Oman)이 걸프 국가들의 지지를 받아 호르무즈 해협을 관리하고 통행 선박에 자발적 통행료를 걷는 방안을 이란에 제시했다. 그러나 테헤란은 자발적 통행료를 포함한 역내 공동관리 제안을 거부한 것으로 전해졌다.","eSum":"Oman has presented Iran with a Gulf-backed plan to manage the Strait of Hormuz, including collecting voluntary fees from transiting ships. Tehran, however, has reportedly ruled out the proposal for regional joint management of the strait.","kImp":"초크포인트의 '통행료화' 시도가 외교 쟁점으로 부상하며 해운 비용 구조에 불확실성을 더한다.","eImp":"Attempts to 'monetize' the chokepoint are becoming a diplomatic flashpoint, adding cost uncertainty for shipping.","url":"https://www.marinelink.com/news/oman-proposes-voluntary-hormuz-transit-541577"},{"code":"HOT","title":"Hormuz toll plan could net Iran and Oman around $7bn a year","src":"agbi","date":"2026-07-28","kSum":"호르무즈 해협 통행료 방안이 시행될 경우 이란과 오만이 연간 약 70억 달러의 수입을 얻을 수 있다고 AGBI가 분석했다. 세계 원유 물동량의 상당 부분이 이 해협을 지나는 만큼 통행료의 경제적 파급력이 크다.","eSum":"AGBI estimates a Hormuz transit toll plan could generate roughly $7 billion a year for Iran and Oman. Given the large share of global crude that passes through the strait, the economic implications of any toll are substantial.","kImp":"통행료 수입 규모가 커 이란의 협상 유인이 강하며 해운 비용 전가 위험이 높다.","eImp":"The sheer revenue at stake strengthens Iran's incentive to bargain and raises the risk of cost pass-through to shipping.","url":"https://www.agbi.com/shipping/2026/07/hormuz-toll-plan-could-net-iran-and-oman-7bn-a-year/"},{"code":"HOT","title":"Hormuz on 'severe' alert as war-risk premiums climb toward 3% of hull value","src":"newarab","date":"2026-07-28","kSum":"미 해군 주도 합동해사정보센터(JMIC)가 호르무즈 통항 경보를 최고 등급인 '심각(severe)'으로 격상했다. 걸프 내 운항 선박의 전쟁위험보험료는 선가의 약 3%까지 올랐고, 상선은 해군 호위 하에 호송선단으로 이동하고 있다. 7월 23일 하루 통항은 평소 약 88척 대비 10척에 그쳤다.","eSum":"The US Navy-led Joint Maritime Information Center raised its Hormuz advisory to the top 'severe' level. War-risk premiums for ships inside the Gulf have climbed toward 3% of vessel value, and merchant ships are moving in convoys under naval escort, with only 10 vessels transiting on 23 July versus a normal ~88 a day.","kImp":"보험료 급등과 통항 급감으로 실질적 해협 봉쇄가 지속되며 원유 공급망 리스크가 고조된다.","eImp":"Soaring premiums and collapsing transits amount to a de facto blockade, escalating crude supply-chain risk.","url":"https://www.newarab.com/news/hormuz-strait-severe-alert-insurance-costs-soar"},{"code":"HOT","title":"Shipping insurance rates surge as Hormuz and Bab al-Mandeb shut down","src":"aljazeera","date":"2026-07-23","kSum":"호르무즈와 바브엘만데브 해협이 사실상 봉쇄되며 해상보험료가 급등하고 있다고 알자지라(Al Jazeera)가 보도했다. 전쟁위험보험은 통상 7일 단위로 판매되며 24~48시간마다 재산정되는데, 걸프 운항 선박의 요율이 계속 상승하고 있다.","eSum":"Shipping insurance rates are surging as the Strait of Hormuz and Bab al-Mandeb effectively shut down, Al Jazeera reports. War-risk cover, typically sold on a seven-day basis and repriced every 24-48 hours, keeps climbing for vessels operating in the Gulf.","kImp":"두 초크포인트의 동시 리스크로 보험·운임 비용이 구조적으로 상승하고 있다.","eImp":"Simultaneous risk at two chokepoints is structurally raising insurance and freight costs.","url":"https://www.aljazeera.com/economy/2026/7/23/how-shipping-insurance-rates-are-rising-as-hormuz-bab-al-mandeb-shut-down"}]},{"code":"SYS","type":"news","kTitle":"Section 20. 해사 IT·소프트웨어","eTitle":"Section 20. Maritime IT & Software","items":[{"code":"SYS","title":"BIMCO to run interoperability pilot for digital seafarer certificate vaults","src":"smartmaritimenetwork","date":"2026-07-29","kSum":"빔코(BIMCO)가 IMO 컴펜디움(Compendium) 데이터 모델을 공통 표준으로 삼아 서로 다른 제공사 플랫폼 간 디지털 선원 증서 데이터 교환을 시연하는 상호운용성 시범사업을 추진한다. 9월 코펜하겐 워크숍에서 인공 선원 신원과 전자증서를 손실 없이 내보내고 이관·수입·표시할 수 있는지 검증한다.","eSum":"BIMCO will run an interoperability pilot to demonstrate the exchange of digital seafarer certificate data across different providers' platforms using the IMO Compendium data model as the common standard. A September Copenhagen workshop will test whether an artificial seafarer identity and e-certificates can be exported, transferred, imported and displayed without data loss.","kImp":"선원 증서 디지털화의 최대 난제인 플랫폼 간 상호운용성 확보를 향한 실질적 진전이다.","eImp":"A concrete step toward solving interoperability, the key obstacle to digitizing seafarer certificates.","url":"https://smartmaritimenetwork.com/2026/07/29/bimco-to-run-interoperability-pilot-for-digital-seafarer-certificate-vaults/"},{"code":"SYS","title":"Rakuten Maritime and Smart Ship Hub fold cybersecurity into fleet performance platform","src":"thedigitalship","date":"2026-07-28","kSum":"라쿠텐마리타임(Rakuten Maritime)이 스마트십허브(Smart Ship Hub)와 손잡고 사이버보안을 디지털 선대관리 플랫폼에 통합했다. 운항 성능과 사이버 회복력을 단일 환경에서 제공하며, 항해계획·기상 라우팅·연료 성능 분석·기관 상태 감시·실시간 선대 진단을 아우른다.","eSum":"Rakuten Maritime has partnered with Smart Ship Hub to integrate cybersecurity into a digital fleet management platform, bringing operational performance and cyber resilience into a single environment. Smart Ship Hub offers voyage planning, weather routing, fuel performance analysis, machinery condition monitoring and real-time fleet diagnostics.","kImp":"성능 최적화와 사이버보안의 결합은 선대관리 SaaS의 새로운 통합 트렌드를 보여준다.","eImp":"Merging performance optimization with cybersecurity signals a new consolidation trend in fleet-management SaaS.","url":"https://thedigitalship.com/news/maritime-software/why-shipowners-are-bringing-cybersecurity-into-fleet-performance-platforms-rakuten-maritime-and-smart-ship-hub-join-forces/"}]},{"code":"SMGR","type":"news","kTitle":"Section 21. 선박관리사 긍정 뉴스","eTitle":"Section 21. Ship Managers (Positive)","items":[{"code":"SMGR","title":"Columbia Group and AD Ports appoint Xanthos Kyriacou as CEO of Noatum CSM","src":"cyprusshippingnews","date":"2026-07-28","kSum":"컬럼비아그룹(Columbia Group)과 AD 포츠그룹(AD Ports Group)의 두바이 합작 선박관리사 노아툼 CSM(Noatum CSM)이 크산토스 키리아쿠(Xanthos Kyriacou)를 신임 CEO로 선임했다. 그는 컬럼비아에서 20여 년간 근무하며 이탈리아·튀르키예·중동 확장을 이끈 인물로, 줄리안 팬터(Julian Panter)의 뒤를 잇는다.","eSum":"Noatum CSM, the Dubai-based ship-management joint venture between Columbia Group and AD Ports Group, has appointed Xanthos Kyriacou as CEO. A more than two-decade Columbia veteran who oversaw expansion across Italy, Turkey and the Middle East, he succeeds Julian Panter.","kImp":"중동 선박관리 합작사의 리더십 강화는 지역 성장 전략의 지속을 보여준다.","eImp":"New leadership at the Middle East JV underscores Columbia's continued regional growth push.","url":"https://cyprusshippingnews.com/2026/07/28/columbia-group-and-ad-ports-group-appoint-xanthos-kyriacou-as-ceo-of-noatum-csm/"},{"code":"SMGR","title":"Columbia Group CEO sets out partnership-model growth agenda amid crewing concerns","src":"allaboutshipping","date":"2026-07-25","kSum":"컬럼비아그룹(Columbia Group) 신임 CEO 마크 하지페트루(Mark Hadjipetrou)가 협력 모델 기반 성장 전략을 제시하며 업계의 선원 부족 심화 가능성에 대한 우려를 던졌다. 파트너십 확대를 통한 선박관리 성장 비전을 강조했다.","eSum":"Columbia Group's new CEO Mark Hadjipetrou has set out a partnership-model growth agenda while flagging concerns about a potential wider crewing shortage. He emphasized expanding through cooperation as the path for ship-management growth.","kImp":"대형 선박관리사가 성장과 인력 확보를 동시 과제로 제시하며 업계 방향성을 시사한다.","eImp":"A major ship manager framing growth and crewing together signals the sector's strategic direction.","url":"https://allaboutshipping.co.uk/2026/07/25/columbia-group-ceo-questions-whether-shipping-is-heading-for-a-wider-crewing-shortage-2/"}]}]};